async function logConnectionStartClicked(userId: string, platform: EhrPlatform, ip?: string, ua?: string) {
  console.log(`[HIPAA-AUDIT][EHR] Connection start: userId=${userId}, platform=${platform}`);
}
async function logConnectionAuthStarted(userId: string, platform: EhrPlatform, connectionId: string, ip?: string, ua?: string) {
  console.log(`[HIPAA-AUDIT][EHR] Auth started: userId=${userId}, platform=${platform}, connectionId=${connectionId}`);
}
async function logConnectionSuccess(userId: string, platform: EhrPlatform, connectionId: string, facilityName: string, ip?: string, ua?: string) {
  console.log(`[HIPAA-AUDIT][EHR] Connection success: userId=${userId}, platform=${platform}, facility=${facilityName}`);
}
async function logConnectionFailed(userId: string, platform: EhrPlatform, connectionId: string | undefined, error: string, ip?: string, ua?: string) {
  console.error(`[HIPAA-AUDIT][EHR] Connection failed: userId=${userId}, platform=${platform}, error=${error}`);
}
