// Simple in-memory rate limiting for 2FA verification
const rateLimitMap = new Map<string, { attempts: number; resetAt: number }>();
const RATE_LIMIT_MAX_ATTEMPTS = 5;
const RATE_LIMIT_WINDOW_MS = 15 * 60 * 1000; // 15 minutes

function checkRateLimit(userId: string): { allowed: boolean; remainingAttempts: number } {
  const now = Date.now();
  const entry = rateLimitMap.get(userId);
  
  if (!entry || now > entry.resetAt) {
    rateLimitMap.set(userId, { attempts: 1, resetAt: now + RATE_LIMIT_WINDOW_MS });
    return { allowed: true, remainingAttempts: RATE_LIMIT_MAX_ATTEMPTS - 1 };
  }
  
  if (entry.attempts >= RATE_LIMIT_MAX_ATTEMPTS) {
    return { allowed: false, remainingAttempts: 0 };
  }
  
  entry.attempts++;
  return { allowed: true, remainingAttempts: RATE_LIMIT_MAX_ATTEMPTS - entry.attempts };
}

function resetRateLimit(userId: string): void {
  rateLimitMap.delete(userId);
}

