  app.get("/api/fasten-connect/config", (req, res) => {
    const publicId = process.env.FASTEN_HEALTH_CLIENT_ID || "public_live_8ccv8p175drs4hw1o7g60120ogh36zp4tama0qd4epdn5";
    const deploymentUrl = process.env.REPLIT_DEPLOYMENT_URL;
    const replitDomains = process.env.REPLIT_DOMAINS || process.env.REPLIT_DEV_DOMAIN || "";
    const primaryDomain = replitDomains.split(",")[0]?.trim();
    let origin: string;
    if (deploymentUrl) {
      origin = deploymentUrl.startsWith("http") ? deploymentUrl : `https://${deploymentUrl}`;
    } else if (primaryDomain) {
      origin = `https://${primaryDomain}`;
    } else {
      const proto = (req.headers["x-forwarded-proto"] as string)?.split(",")[0]?.trim() || req.protocol || "https";
      const host = (req.headers["x-forwarded-host"] as string) || req.headers.host || "";
      origin = `${proto}://${host}`;
    }
    const redirectUri = `${origin}/api/fasten-connect/callback`;
    console.log("[FastenConnect] Config requested - publicId present:", !!publicId, "redirectUri:", redirectUri);
    res.json({ publicId, redirectUri });
  });

  app.get("/api/fasten-connect/callback", (req, res) => {
    const { authorization_code, connection_status, request_id, external_id, error, error_description } = req.query;
    const timestamp = new Date().toISOString();
    console.log(`[HIPAA-AUDIT][FastenConnect] ${timestamp} - CALLBACK_RECEIVED - Status:${connection_status} RequestId:${request_id} HasAuthCode:${!!authorization_code} ExternalId:${external_id || "none"}`);

    if (error) {
      console.error(`[FastenConnect] Callback error: ${error} - ${error_description}`);
      return res.redirect(`/ehr-callback?status=failed&error_description=${encodeURIComponent(String(error_description || error))}`);
    }

    const status = connection_status === "authorized" || authorization_code ? "authorized" : (connection_status || "unknown");
    res.redirect(`/ehr-callback?status=${status === "authorized" ? "authorized" : status}&connection_status=${status}&request_id=${request_id || ""}`);
  });

  app.post("/api/fasten-connect/webhook", (req, res) => {
    const event = req.body;
    const timestamp = new Date().toISOString();
    console.log(`[HIPAA-AUDIT][FastenConnect] ${timestamp} - WEBHOOK_EVENT - Type:${event?.event_type || "unknown"} - ${JSON.stringify(event)}`);
    res.status(200).json({ received: true });
  });

