  // Dashboard Stats
  app.get("/api/dashboard/stats", async (req, res) => {
    try {
      const connections = await storage.getEhrConnections();
      const unifiedPatients = await storage.getUnifiedPatients();
      const patients = await storage.getPatients();
      const appointments = await storage.getUpcomingAppointments();
      
      let totalRecords = 0;
      let activeMedications = 0;
      
      for (const patient of patients) {
        const records = await storage.getMedicalRecordsByPatient(patient.id);
        const meds = await storage.getMedicationsByPatient(patient.id);
        totalRecords += records.length;
        activeMedications += meds.filter(m => m.status === 'active').length;
      }

      res.json({
        totalPatients: unifiedPatients.length, // Count unique patients, not EHR records
        activeConnections: connections.filter(c => c.status === 'connected').length,
        totalRecords,
        activeMedications,
        upcomingAppointments: appointments.length,
        ehrSources: patients.length, // Total patient records across all EHR platforms
        recentSyncs: connections.filter(c => {
          const lastSync = new Date(c.lastSync);
          const dayAgo = new Date(Date.now() - 86400000);
          return lastSync > dayAgo;
        }).length,
      });
    } catch (error) {
      console.error("Error fetching dashboard stats:", error);
      res.status(500).json({ error: "Failed to fetch dashboard stats" });
    }
  });

