  // Deduplication Summary - overview of detected duplicates across all record types
  app.get("/api/deduplication/summary", requirePermission("records:read"), async (req, res) => {
    try {
      const connections = await storage.getEhrConnections();
      const patients = await storage.getPatients();
      
      const allMedications: any[] = [];
      const allAllergies: any[] = [];
      const allProblems: any[] = [];
      const allRecords: any[] = [];

      for (const patient of patients) {
        const connection = connections.find(c => c.id === patient.ehrConnectionId);
        const sourceFacility = connection?.facilityName || 'Unknown';
        const sourcePlatform = connection?.platform || 'unknown';

        const medications = await storage.getMedicationsByPatient(patient.id);
        medications.forEach(med => allMedications.push({ ...med, sourceFacility, sourcePlatform }));

        const allergies = await storage.getAllergiesByPatient(patient.id);
        allergies.forEach(allergy => allAllergies.push({ ...allergy, sourceFacility, sourcePlatform }));

        const problems = await storage.getProblemsByPatient(patient.id);
        problems.forEach(problem => allProblems.push({ ...problem, sourceFacility, sourcePlatform }));

        const records = await storage.getMedicalRecordsByPatient(patient.id);
        records.forEach(record => allRecords.push({ ...record, sourceFacility, sourcePlatform }));
      }

      const medResult = deduplicateMedications(allMedications);
      const allergyResult = deduplicateAllergies(allAllergies);
      const problemResult = deduplicateProblems(allProblems);
      const recordResult = deduplicateMedicalRecords(allRecords);

      const summary = generateDeduplicationSummary(
        medResult.stats,
        allergyResult.stats,
        problemResult.stats,
        recordResult.stats
      );

      res.json({
        summary,
        medicationGroups: medResult.groups.slice(0, 10).map(g => ({
          name: g.primaryItem.name,
          duplicateCount: g.duplicates.length,
          hasConflicts: g.conflicts.length > 0,
        })),
        allergyGroups: allergyResult.groups.slice(0, 10).map(g => ({
          name: g.primaryItem.name,
          duplicateCount: g.duplicates.length,
          hasConflicts: g.conflicts.length > 0,
        })),
        problemGroups: problemResult.groups.slice(0, 10).map(g => ({
          name: g.primaryItem.name,
          icdCode: g.primaryItem.icdCode,
          duplicateCount: g.duplicates.length,
          hasConflicts: g.conflicts.length > 0,
        })),
      });
    } catch (error) {
      console.error("Error generating deduplication summary:", error);
      res.status(500).json({ error: "Failed to generate deduplication summary" });
    }
  });

