  // Initiate SMART on FHIR OAuth authorization
  app.post("/api/ehr-connections/authorize", requirePermission("connections:write"), requireConsents, auditDataAccess("ehr-connections", "authorize"), async (req, res) => {
    try {
      const user = req.user as any;
      if (!user) {
        return res.status(401).json({ error: "Not authenticated" });
      }

      const userId = user.claims?.sub || user.id;
      if (!userId) {
        return res.status(401).json({ error: "Unable to determine user identity" });
      }
      const { platform, facilityName, clientId, fhirBaseUrl } = req.body;
      const ipAddress = req.ip || req.headers["x-forwarded-for"]?.toString() || "Unknown";
      const userAgent = req.headers["user-agent"] || "Unknown";
      
      if (!platform || !ehrPlatforms.includes(platform)) {
        return res.status(400).json({ error: "Invalid platform" });
      }

      await logConnectionStartClicked(userId, platform as EhrPlatform, ipAddress, userAgent);

      const preset = FHIR_PRESETS[platform as EhrPlatform];
      const activeConfig = getActiveConfig(preset);

      const fhirConfig = {
        fhirBaseUrl: fhirBaseUrl || activeConfig.fhirBaseUrl,
        authorizationEndpoint: activeConfig.authorizationEndpoint,
        tokenEndpoint: activeConfig.tokenEndpoint,
        issuer: activeConfig.issuer || platform,
        scopes: activeConfig.scopes,
        clientId: clientId || activeConfig.clientId || "",
        usePkce: activeConfig.usePkce ?? true,
      };
      const presetName = preset.name;

      if (!fhirConfig.clientId && platform !== "fastenhealth") {
        return res.status(400).json({ 
          error: `No client ID configured for ${presetName}. Please set the ${platform.toUpperCase()}_CLIENT_ID environment variable or provide a clientId.` 
        });
      }

      const connection = await storage.createEhrConnection({
        userId: userId,
        platform: platform as EhrPlatform,
        facilityName: facilityName || presetName,
        status: "pending_auth",
        fhirConfig,
      });

      const state = generateState();
      const codeVerifier = generateCodeVerifier();
      const codeChallenge = generateCodeChallenge(codeVerifier);

      const deploymentUrl = process.env.REPLIT_DEPLOYMENT_URL;
      const devDomain = process.env.REPLIT_DEV_DOMAIN;
      const baseUrl = deploymentUrl
        ? deploymentUrl.startsWith("http") ? deploymentUrl : `https://${deploymentUrl}`
        : devDomain
          ? `https://${devDomain}`
          : `http://localhost:5000`;
      const redirectUri = `${baseUrl}/api/ehr-connections/callback`;

      await storage.createOAuthPendingState({
        userId: userId,
        ehrConnectionId: connection.id,
        state,
        codeVerifier,
        redirectUri,
      });

      const authUrl = buildAuthorizationUrl({
        fhirConfig,
        redirectUri,
        state,
        codeChallenge,
        clientId: fhirConfig.clientId,
      });

      await logConnectionAuthStarted(userId, platform as EhrPlatform, connection.id, ipAddress, userAgent);

      res.json({ authUrl, connectionId: connection.id });
    } catch (error) {
      console.error("Error initiating OAuth:", error);
      res.status(500).json({ error: "Failed to initiate authorization" });
    }
  });

  // OAuth callback for SMART on FHIR
  app.get("/api/ehr-connections/callback", async (req, res) => {
    try {
      const { code, state, error, error_description } = req.query;
      const ipAddress = req.ip || req.headers["x-forwarded-for"]?.toString() || "Unknown";
      const userAgent = req.headers["user-agent"] || "Unknown";

      if (error) {
        console.error("OAuth error:", error, error_description);
        // Log OAuth error from provider
        const pendingState = state ? await storage.getOAuthPendingState(String(state)) : null;
        if (pendingState) {
          const conn = await storage.getEhrConnection(pendingState.ehrConnectionId);
          if (conn) {
            await logConnectionFailed(
              conn.userId,
              conn.platform,
              conn.id,
              `OAuth denied: ${error_description || error}`,
              ipAddress,
              userAgent
            );
          }
        }
        return res.redirect(`/connections?error=${encodeURIComponent(String(error_description || error))}`);
      }

      if (!code || !state) {
        return res.redirect("/connections?error=Missing+authorization+code");
      }

      const pendingState = await storage.getOAuthPendingState(String(state));
      if (!pendingState) {
        return res.redirect("/connections?error=Invalid+or+expired+authorization+state");
      }

      const connection = await storage.getEhrConnection(pendingState.ehrConnectionId);
      if (!connection || !connection.fhirConfig) {
        return res.redirect("/connections?error=Connection+not+found");
      }

      try {
        const { tokens, smartContext } = await exchangeCodeForTokens({
          fhirConfig: connection.fhirConfig,
          code: String(code),
          redirectUri: pendingState.redirectUri,
          codeVerifier: pendingState.codeVerifier,
          clientId: connection.fhirConfig.clientId,
        });

        await storage.updateEhrConnectionTokens(connection.id, tokens, smartContext);
        await storage.deleteOAuthPendingState(String(state));

        // Log connection success analytics event
        await logConnectionSuccess(
          connection.userId,
          connection.platform,
          connection.id,
          connection.facilityName,
          ipAddress,
          userAgent
        );

        res.redirect(`/connections?connected=${connection.id}`);
      } catch (tokenError) {
        console.error("Token exchange error:", tokenError);
        const errorMessage = tokenError instanceof Error ? tokenError.message : "Token exchange failed";
        
        // Log connection failure analytics event
        await logConnectionFailed(
          connection.userId,
          connection.platform,
          connection.id,
          errorMessage,
          ipAddress,
          userAgent
        );

        await storage.updateEhrConnection(connection.id, {
          status: "error",
          syncError: errorMessage,
        });
        res.redirect(`/connections?error=Token+exchange+failed`);
      }
    } catch (error) {
      console.error("OAuth callback error:", error);
      res.redirect("/connections?error=Authorization+failed");
    }
  });

  // Sync data from a connected EHR using FHIR
  app.post("/api/ehr-connections/:id/fhir-sync", requirePermission("connections:write"), requireConsents, auditDataAccess("ehr-connections", "fhir-sync"), async (req, res) => {
    const startTime = Date.now();
    const ipAddress = req.ip || req.headers["x-forwarded-for"]?.toString() || "Unknown";
    const userAgent = req.headers["user-agent"] || "Unknown";
    const triggerType = (req.body?.triggerType as "manual" | "scheduled" | "retry") || "manual";
    
    try {
      const connection = await storage.getEhrConnection(req.params.id);
      if (!connection) {
        return res.status(404).json({ error: "Connection not found" });
      }

      if (!connection.tokens || !connection.fhirConfig) {
        return res.status(400).json({ error: "Connection is not authenticated" });
      }

      // Check for token expiry before sync and log if expired
      const isExpired = await checkConnectionTokenExpiry(connection);
      if (isExpired) {
        return res.status(401).json({ 
          error: "Connection token expired", 
          status: "expired",
          message: "Please re-authorize the connection to continue syncing data."
        });
      }

      // Log sync triggered event
      await logSyncTriggered(connection.userId, connection.platform, connection.id, triggerType, ipAddress, userAgent);

      const result = await syncEhrConnection(connection);
      const duration = Date.now() - startTime;
      const recordsAdded = result.patientsAdded + result.recordsAdded + result.medicationsAdded + result.vitalsAdded;
      const partialSync = result.errors.length > 0 && result.success;
      
      // Update connection with sync result
      await storage.updateEhrConnection(connection.id, {
        lastSyncResult: {
          success: result.success,
          recordsAdded,
          errors: result.errors,
          partialSync,
          duration,
        },
        syncSettings: {
          autoSyncEnabled: connection.syncSettings?.autoSyncEnabled ?? true,
          syncInterval: connection.syncSettings?.syncInterval ?? "4hours",
          lastScheduledSync: connection.syncSettings?.lastScheduledSync,
          nextScheduledSync: connection.syncSettings?.nextScheduledSync,
          retryCount: result.success ? 0 : (connection.syncSettings?.retryCount || 0) + 1,
          maxRetries: connection.syncSettings?.maxRetries ?? 3,
        },
      });

      if (result.success || partialSync) {
        // Log sync completed
        await logSyncCompleted(connection.userId, connection.platform, connection.id, recordsAdded, duration, partialSync, ipAddress, userAgent);
      } else {
        // Log sync failed
        await logSyncFailed(connection.userId, connection.platform, connection.id, result.errors.join(", "), connection.syncSettings?.retryCount || 0, ipAddress, userAgent);
      }

      res.json({
        ...result,
        partialSync,
        duration,
      });
    } catch (error) {
      const duration = Date.now() - startTime;
      const errorMessage = error instanceof Error ? error.message : String(error);
      console.error("Error syncing FHIR data:", error);
      
      // Log sync failed
      const connection = await storage.getEhrConnection(req.params.id);
      if (connection) {
        await logSyncFailed(connection.userId, connection.platform, connection.id, errorMessage, connection.syncSettings?.retryCount || 0, ipAddress, userAgent);
      }
      
      res.status(500).json({ error: "Failed to sync FHIR data", message: errorMessage });
    }
  });

  // Retry sync for failed connections
  app.post("/api/ehr-connections/:id/retry-sync", requirePermission("connections:write"), async (req, res) => {
    const ipAddress = req.ip || req.headers["x-forwarded-for"]?.toString() || "Unknown";
    const userAgent = req.headers["user-agent"] || "Unknown";
    
    try {
      const connection = await storage.getEhrConnection(req.params.id);
      if (!connection) {
        return res.status(404).json({ error: "Connection not found" });
      }

      // Log retry clicked event
      await logSyncRetryClicked(connection.userId, connection.platform, connection.id, ipAddress, userAgent);

      // Reset error status and trigger sync
      await storage.updateEhrConnection(connection.id, { 
        status: "connected",
        syncError: undefined,
      });

      // Forward to the main sync endpoint with retry trigger type
      req.body = { triggerType: "retry" };
      
      res.json({ message: "Sync retry initiated", connectionId: connection.id });
    } catch (error) {
      console.error("Error retrying sync:", error);
      res.status(500).json({ error: "Failed to retry sync" });
    }
  });

  // Update sync settings for a connection
  app.patch("/api/ehr-connections/:id/sync-settings", requirePermission("connections:write"), async (req, res) => {
    try {
      const connection = await storage.getEhrConnection(req.params.id);
      if (!connection) {
        return res.status(404).json({ error: "Connection not found" });
      }

      const { autoSyncEnabled, syncInterval } = req.body;
      const updatedSettings = {
        ...connection.syncSettings,
        autoSyncEnabled: autoSyncEnabled ?? connection.syncSettings?.autoSyncEnabled ?? true,
        syncInterval: syncInterval ?? connection.syncSettings?.syncInterval ?? "4hours",
      };

      // Calculate next scheduled sync if auto-sync is enabled
      if (updatedSettings.autoSyncEnabled && updatedSettings.syncInterval !== "manual") {
        const intervalMs = getSyncIntervalMs(updatedSettings.syncInterval);
        updatedSettings.nextScheduledSync = new Date(Date.now() + intervalMs).toISOString();
      } else {
        updatedSettings.nextScheduledSync = undefined;
      }

      await storage.updateEhrConnection(connection.id, { syncSettings: updatedSettings });
      
      res.json({ message: "Sync settings updated", syncSettings: updatedSettings });
    } catch (error) {
      console.error("Error updating sync settings:", error);
      res.status(500).json({ error: "Failed to update sync settings" });
    }
  });

