  // Reconnect an expired connection (initiates re-authorization)
  app.post("/api/ehr-connections/:id/reconnect", requirePermission("connections:write"), async (req, res) => {
    const ipAddress = req.ip || req.headers["x-forwarded-for"]?.toString() || "Unknown";
    const userAgent = req.headers["user-agent"] || "Unknown";
    
    try {
      const connection = await storage.getEhrConnection(req.params.id);
      if (!connection) {
        return res.status(404).json({ error: "Connection not found" });
      }

      if (connection.status !== "expired" && connection.status !== "error") {
        return res.status(400).json({ error: "Connection does not need reconnection" });
      }

      // Reset connection to pending_auth for re-authorization
      await storage.updateEhrConnection(connection.id, { 
        status: "pending_auth",
        syncError: undefined,
      });

      // Log reconnection attempt
      await logConnectionStartClicked(connection.userId, connection.platform, ipAddress, userAgent);

      res.json({ 
        message: "Ready for reconnection", 
        connectionId: connection.id,
        platform: connection.platform,
        facilityName: connection.facilityName,
      });
    } catch (error) {
      console.error("Error initiating reconnect:", error);
      res.status(500).json({ error: "Failed to initiate reconnection" });
    }
  });

