  // Delete Medical Record with ownership-scoped storage (IDOR protection)
  app.delete("/api/health-records/:id", requirePermission("records:write"), auditDataAccess("records", "delete"), async (req, res) => {
    try {
      const { id } = req.params;
      const user = req.user as any;
      const userId = user?.claims?.sub;
      
      if (!userId) {
        return res.status(401).json({ error: "Authentication required" });
      }
      
      const userRole = user?.claims?.role || "patient";
      
      // Admin/provider bypass: use unscoped method
      if (userRole === "admin" || userRole === "provider") {
        const record = await storage.getMedicalRecord(id);
        if (!record) {
          return res.status(404).json({ error: "Record not found" });
        }
        await storage.softDeleteMedicalRecord(id, userId);
        await logPhiAccess({
          userId,
          action: "delete",
          resourceType: "medical_record",
          resourceId: id,
          details: JSON.stringify({ recordType: record.type, deletedAt: new Date().toISOString(), adminOverride: true }),
          timestamp: new Date().toISOString(),
        });
        return res.json({ success: true, message: "Record deleted successfully" });
      }
      
      // Regular user: use ownership-scoped delete (prevents IDOR)
      const deleted = await storage.deleteMedicalRecordForUser(userId, id);
      
      if (!deleted) {
        // Log denied access attempt
        await logPhiAccess({
          userId,
          action: "delete_denied",
          resourceType: "medical_record",
          resourceId: id,
          details: JSON.stringify({ reason: "ownership_violation_or_not_found" }),
          timestamp: new Date().toISOString(),
        });
        return res.status(404).json({ error: "Record not found or not authorized" });
      }
      
      // Log successful deletion
      await logPhiAccess({
        userId,
        action: "delete",
        resourceType: "medical_record",
        resourceId: id,
        details: JSON.stringify({ deletedAt: new Date().toISOString() }),
        timestamp: new Date().toISOString(),
      });
      
      res.json({ success: true, message: "Record deleted successfully" });
    } catch (error) {
      console.error("Error deleting medical record:", error);
      res.status(500).json({ error: "Failed to delete medical record" });
    }
  });

