  // Allergies with deduplication
  app.get("/api/allergies", requirePermission("conditions:read"), auditDataAccess("allergies", "list"), async (req, res) => {
    try {
      const allergies = await storage.getAllergies();
      const connections = await storage.getEhrConnections();
      const enrichedAllergies = allergies.map(allergy => {
        const connection = connections.find(c => c.id === allergy.ehrConnectionId);
        return {
          ...allergy,
          sourceFacility: connection?.facilityName || "Unknown",
          sourcePlatform: connection?.platform || "unknown",
        };
      });

      const { results, groups, stats } = deduplicateAllergies(enrichedAllergies);

      const allergiesWithDedup = results.map(result => ({
        ...result.item,
        isPrimary: result.isPrimary,
        duplicateGroupId: result.duplicateGroupId,
        matchConfidence: result.matchConfidence,
        conflictDetails: result.conflictDetails,
      }));

      allergiesWithDedup.sort((a, b) => {
        const severityOrder = { life_threatening: 0, severe: 1, moderate: 2, mild: 3 };
        const aSev = severityOrder[a.severity as keyof typeof severityOrder] ?? 4;
        const bSev = severityOrder[b.severity as keyof typeof severityOrder] ?? 4;
        if (aSev !== bSev) return aSev - bSev;
        if (a.status === 'active' && b.status !== 'active') return -1;
        if (a.status !== 'active' && b.status === 'active') return 1;
        return a.name.localeCompare(b.name);
      });

      res.json({
        allergies: allergiesWithDedup,
        deduplication: {
          stats,
          groups: groups.map(g => ({
            groupId: g.groupId,
            primaryAllergy: g.primaryItem.name,
            duplicateCount: g.duplicates.length,
            matchConfidence: g.matchConfidence,
            conflicts: g.conflicts,
          })),
        },
      });
    } catch (error) {
      console.error("Error fetching allergies:", error);
      res.status(500).json({ error: "Failed to fetch allergies" });
    }
  });

