      if (!existing) return res.status(404).json({ error: "Transfer request not found" });
      
      const updated = await storage.updateTransferRequest(req.params.id, req.body);
      
      if (updated && req.body.status && req.body.status !== existing.status) {
        const { generateTransferStatusNotification } = await import("./pharmacy-ai");
        await generateTransferStatusNotification(updated, req.body.status);
      }
      
