  app.get("/api/documents", requirePermission("documents:read"), auditDataAccess("documents", "list"), async (req, res) => {
    try {
      const connections = await storage.getEhrConnections();
      const patients = await storage.getPatients();
      const documents: any[] = [];

      for (const patient of patients) {
        const connection = connections.find(c => c.id === patient.ehrConnectionId);
        const records = await storage.getMedicalRecordsByPatient(patient.id);

        // Convert relevant medical records to documents
        for (const record of records) {
          let docType = 'clinical_note';
          if (record.type === 'lab_result') docType = 'lab_report';
          if (record.type === 'imaging') docType = 'imaging_report';
          if (record.type === 'procedure') docType = 'clinical_note';

          documents.push({
            id: `doc-${record.id}`,
            patientId: record.patientId,
            ehrConnectionId: record.ehrConnectionId,
            type: docType,
            title: record.title,
            description: record.description,
            date: record.date,
            provider: record.provider,
            facility: record.facility,
            content: record.description,
            mimeType: 'text/plain',
            sourceFacility: connection?.facilityName || 'Unknown',
            sourcePlatform: connection?.platform || 'unknown',
          });
        }
      }

      // Sort by date, most recent first
      documents.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
      res.json(documents);
    } catch (error) {
      console.error("Error fetching documents:", error);
      res.status(500).json({ error: "Failed to fetch documents" });
    }
  });

