  // Helper function to check caregiver access to a patient's PHI
  async function checkCaregiverPhiAccess(
    caregiverUserId: string,
    patientUserId: string,
    requiredPermission: string,
    resourceType: string,
    action: string,
    ipAddress?: string,
    userAgent?: string
  ): Promise<{ allowed: boolean; caregiver?: import("@shared/schema").Caregiver; reason?: string }> {
    // Get all caregivers for this patient
    const caregivers = await storage.getCaregivers(patientUserId);
    const caregiver = caregivers.find(c => c.caregiverUserId === caregiverUserId && c.status === "accepted");
    
    if (!caregiver) {
      return { allowed: false, reason: "Not authorized as a caregiver for this patient" };
    }

    // Check if caregiver is suspended
    if (caregiver.status === "suspended") {
      await storage.createCaregiverAccessLog({
        caregiverId: caregiver.id,
        caregiverName: caregiver.caregiverName || "Unknown",
        patientUserId,
        accessType: "view",
        resourceType,
        action,
        ipAddress,
        userAgent,
        approved: false,
        emergencyOverride: false,
        patientNotified: false,
      });
      return { allowed: false, caregiver, reason: "Caregiver access is suspended" };
    }

    // Check time-limited access expiration
    if (caregiver.accessRestriction === "time_limited" && caregiver.accessExpiresAt) {
      if (new Date(caregiver.accessExpiresAt) < new Date()) {
        await storage.createCaregiverAccessLog({
          caregiverId: caregiver.id,
          caregiverName: caregiver.caregiverName || "Unknown",
          patientUserId,
          accessType: "view",
          resourceType,
          action,
          ipAddress,
          userAgent,
          approved: false,
          emergencyOverride: false,
          patientNotified: false,
        });
        return { allowed: false, caregiver, reason: "Caregiver access has expired" };
      }
    }

    // Check if permission requires approval
    if (caregiver.requiresApprovalFor?.includes(requiredPermission)) {
      // Check if there's an approved access request for this permission
      const requests = await storage.getCaregiverAccessRequests(patientUserId);
      const approvedRequest = requests.find(r => 
        r.caregiverId === caregiver.id && 
        r.requestedPermission === requiredPermission && 
        r.status === "approved"
      );
      if (!approvedRequest) {
        await storage.createCaregiverAccessLog({
          caregiverId: caregiver.id,
          caregiverName: caregiver.caregiverName || "Unknown",
          patientUserId,
          accessType: "view",
          resourceType,
          action,
          ipAddress,
          userAgent,
          approved: false,
          emergencyOverride: false,
          patientNotified: true,
        });
        return { allowed: false, caregiver, reason: "This permission requires patient approval" };
      }
    }

    // Check if caregiver has the required permission
    if (!caregiver.permissions.includes(requiredPermission) && !caregiver.permissions.includes("all_access")) {
      await storage.createCaregiverAccessLog({
        caregiverId: caregiver.id,
        caregiverName: caregiver.caregiverName || "Unknown",
        patientUserId,
        accessType: "view",
        resourceType,
        action,
        ipAddress,
        userAgent,
        approved: false,
        emergencyOverride: false,
        patientNotified: false,
      });
      return { allowed: false, caregiver, reason: `Missing required permission: ${requiredPermission}` };
    }

    // Access granted - log successful access
    await storage.createCaregiverAccessLog({
      caregiverId: caregiver.id,
      caregiverName: caregiver.caregiverName || "Unknown",
      patientUserId,
      accessType: action === "read" ? "view" : "action",
      resourceType,
      action,
      ipAddress,
      userAgent,
      approved: true,
      emergencyOverride: false,
      patientNotified: caregiver.notifyPatientOnAccess || false,
    });

    // Update last access time
    await storage.updateCaregiver(caregiver.id, { lastAccessAt: new Date().toISOString() });

    return { allowed: true, caregiver };
  }

  // Endpoint for caregivers to access patient medications with permission check
  app.get("/api/caregiver-access/:patientUserId/medications", requireRole("caregiver"), async (req, res) => {
    try {
      const user = req.user as any;
      if (!user?.claims?.sub) {
        return res.status(401).json({ error: "Unauthorized" });
      }

      const { patientUserId } = req.params;
      const accessCheck = await checkCaregiverPhiAccess(
        user.claims.sub,
        patientUserId,
        "view_medications",
        "medications",
        "read",
        req.ip,
        req.get("user-agent")
      );

      if (!accessCheck.allowed) {
        return res.status(403).json({ error: accessCheck.reason });
      }

      const medications = await storage.getMedicationsByPatient(patientUserId);
      
      await logPhiAccess({
        userId: user.claims.sub,
        userRole: "caregiver",
        patientId: patientUserId,
        resourceType: "medications",
        action: "read",
        details: `Caregiver accessed ${medications.length} medications for patient`,
      });

      res.json(medications);
    } catch (error) {
      console.error("Error accessing patient medications:", error);
      res.status(500).json({ error: "Failed to access medications" });
    }
  });

