  // Review access request (patient only)
  app.post("/api/caregivers/access-requests/:id/review", requirePermission("caregivers:manage"), async (req, res) => {
    try {
      const user = req.user as any;
      if (!user?.claims?.sub) {
        return res.status(401).json({ error: "Unauthorized" });
      }

      const { approved, notes } = req.body;
      if (typeof approved !== "boolean") {
        return res.status(400).json({ error: "approved field is required (boolean)" });
      }

      const userId = user.claims.sub;
      const updated = await storage.reviewCaregiverAccessRequest(req.params.id, userId, approved, notes);
      
      if (!updated) {
        return res.status(404).json({ error: "Access request not found or not authorized" });
      }

      // If approved, update the caregiver's permissions
      if (approved && updated.caregiverId) {
        const caregiver = await storage.getCaregiver(updated.caregiverId);
        if (caregiver) {
          const newPermissions = [...new Set([...caregiver.permissions, updated.requestedPermission])];
          await storage.updateCaregiverPermissions(caregiver.id, userId, {
            permissions: newPermissions as any,
          });
        }
      }

      await logPhiAccess({
        userId,
        userRole: (req as any).userRole || "patient",
        resourceType: "caregiver_access_request",
        resourceId: req.params.id,
        action: "write",
        details: `${approved ? "Approved" : "Denied"} access request for: ${updated.requestedPermission}`,
      });

      res.json(updated);
    } catch (error) {
      console.error("Error reviewing access request:", error);
      res.status(500).json({ error: "Failed to review access request" });
    }
  });

