  app.delete("/api/security/sessions/:id", requirePermission("security:write"), async (req, res) => {
    try {
      const user = req.user as any;
      if (!user?.claims?.sub) {
        return res.status(401).json({ error: "Unauthorized" });
      }

      await storage.deleteUserSession(req.params.id, user.claims.sub);

      await storage.createSecurityAuditLog({
        userId: user.claims.sub,
        eventType: "session_revoked",
        description: "A session was revoked",
        ipAddress: req.ip || "Unknown",
        userAgent: req.get("user-agent") || "Unknown",
        metadata: { sessionId: req.params.id },
      });

      // Check if user wants session activity alerts
      const settings = await storage.getSecuritySettings(user.claims.sub);
      if (settings?.sessionActivityAlerts) {
        await storage.createSecurityNotification({
          userId: user.claims.sub,
          type: "session_activity",
          title: "Session Revoked",
          message: "A session was remotely signed out from your account.",
          severity: "info",
          metadata: { sessionId: req.params.id },
        });
      }

      res.json({ success: true });
    } catch (error) {
      console.error("Error revoking session:", error);
      res.status(500).json({ error: "Failed to revoke session" });
    }
  });

