  // Admin: Update user role (admin only)
  app.patch("/api/admin/users/:userId/role", requireRole("admin"), async (req, res) => {
    try {
      const user = req.user as any;
      const targetUserId = req.params.userId;
      const { role: newRole } = req.body;

      if (!userRoles.includes(newRole)) {
        return res.status(400).json({ 
          error: "Invalid role",
          validRoles: userRoles,
        });
      }

      const targetUser = await storage.getUser(targetUserId);
      if (!targetUser) {
        return res.status(404).json({ error: "User not found" });
      }

      const oldRole = targetUser.role;
      
      if (oldRole === newRole) {
        return res.status(400).json({ error: "User already has this role" });
      }

      // Prevent admin from removing their own admin role
      if (user.claims.sub === targetUserId && oldRole === "admin" && newRole !== "admin") {
        return res.status(400).json({ error: "Cannot remove your own admin role" });
      }

      const updatedUser = await storage.updateUserRole(targetUserId, newRole);

      await logRoleChange(
        user.claims.sub,
        targetUserId,
        oldRole,
        newRole,
        req.ip || "Unknown",
        req.get("user-agent") || "Unknown"
      );

      res.json({
        success: true,
        user: {
          id: updatedUser?.id,
          email: updatedUser?.email,
          firstName: updatedUser?.firstName,
          lastName: updatedUser?.lastName,
          role: updatedUser?.role,
          isActive: updatedUser?.isActive,
        },
        previousRole: oldRole,
        newRole,
      });
    } catch (error) {
      console.error("Error updating user role:", error);
      res.status(500).json({ error: "Failed to update user role" });
    }
  });

