  // Send a message to the AI assistant
  app.post("/api/assistant/conversations/:id/messages", requirePermission("records:read"), async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub || "current-user";
      const { message, patientId, language } = req.body;
      
      if (!message || message.trim().length === 0) {
        return res.status(400).json({ error: "Message is required" });
      }
      
      const conversation = await storage.getAssistantConversation(req.params.id);
      if (!conversation || conversation.userId !== userId) {
        return res.status(404).json({ error: "Conversation not found" });
      }
      
      // Save user message
      const userMessage = await storage.createAssistantMessage({
        conversationId: conversation.id,
        role: "user",
        content: message,
        metadata: { language },
      });
      
      // Get patient health context
      const targetPatientId = patientId || conversation.patientId;
      let healthContext = {
        medications: [] as any[],
        allergies: [] as any[],
        conditions: [] as any[],
        labResults: [] as any[],
        recentRecords: [] as any[],
      };
      
      if (targetPatientId) {
        healthContext = await getPatientHealthContext(targetPatientId);
      } else {
        // Get first patient's data as fallback
        const patients = await storage.getPatients();
        if (patients.length > 0) {
          healthContext = await getPatientHealthContext(patients[0].id);
        }
      }
      
      // Get conversation history
      const messages = await storage.getAssistantMessages(conversation.id);
      
      // Generate AI response
      const response = await generateAssistantResponse(
        message,
        messages.slice(0, -1), // Exclude the just-added user message
        healthContext,
        { userId, patientId: targetPatientId || undefined, language }
      );
      
      // Save assistant response
      const assistantMessage = await storage.createAssistantMessage({
        conversationId: conversation.id,
        role: "assistant",
        content: response.content,
        metadata: response.metadata,
      });
      
      // Update conversation title if it's the first message
      const isDefaultTitle = !conversation.title || conversation.title === "New Conversation";
      if (messages.length <= 1 && isDefaultTitle) {
        const title = await generateConversationTitle(message);
        await storage.updateAssistantConversation(conversation.id, { title });
      }
      
      res.json({
        userMessage,
        assistantMessage,
      });
    } catch (error) {
      console.error("Error sending message:", error);
      res.status(500).json({ error: "Failed to send message" });
    }
  });

  // Stream AI assistant response
  app.post("/api/assistant/conversations/:id/stream", requirePermission("records:read"), async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub || "current-user";
      const { message, patientId, language } = req.body;
      
      if (!message || message.trim().length === 0) {
        return res.status(400).json({ error: "Message is required" });
      }
      
      const conversation = await storage.getAssistantConversation(req.params.id);
      if (!conversation || conversation.userId !== userId) {
        return res.status(404).json({ error: "Conversation not found" });
      }
      
      // Save user message
      await storage.createAssistantMessage({
        conversationId: conversation.id,
        role: "user",
        content: message,
        metadata: { language },
      });
      
      // Get patient health context
      const targetPatientId = patientId || conversation.patientId;
      let healthContext = {
        medications: [] as any[],
        allergies: [] as any[],
        conditions: [] as any[],
        labResults: [] as any[],
        recentRecords: [] as any[],
      };
      
      if (targetPatientId) {
        healthContext = await getPatientHealthContext(targetPatientId);
      } else {
        const patients = await storage.getPatients();
        if (patients.length > 0) {
          healthContext = await getPatientHealthContext(patients[0].id);
        }
      }
      
      // Get conversation history
      const messages = await storage.getAssistantMessages(conversation.id);
      
      // Set up SSE
      res.setHeader("Content-Type", "text/event-stream");
      res.setHeader("Cache-Control", "no-cache");
      res.setHeader("Connection", "keep-alive");
      
      let fullContent = '';
      
      const stream = streamAssistantResponse(
        message,
        messages.slice(0, -1),
        healthContext,
        { userId, patientId: targetPatientId || undefined, language }
      );
      
      for await (const chunk of stream) {
        if (chunk.type === 'content' && typeof chunk.data === 'string') {
          fullContent += chunk.data;
          res.write(`data: ${JSON.stringify({ type: 'content', data: chunk.data })}\n\n`);
        } else if (chunk.type === 'done') {
          const result = chunk.data as StreamResult;
          
          // Save the complete assistant message with metadata
          const assistantMessage = await storage.createAssistantMessage({
            conversationId: conversation.id,
            role: "assistant",
            content: result.fullContent,
            metadata: result.metadata,
          });
          
          // Generate conversation title if this is the first exchange
          const allMessages = await storage.getAssistantMessages(conversation.id);
          const isDefaultTitle = !conversation.title || conversation.title === "New Conversation";
          if (allMessages.length === 2 && isDefaultTitle) {
            const title = await generateConversationTitle(message);
            await storage.updateAssistantConversation(conversation.id, { title });
          }
          
          res.write(`data: ${JSON.stringify({ 
            type: 'done', 
            messageId: assistantMessage.id,
            title: (await storage.getAssistantConversation(conversation.id))?.title,
            metadata: result.metadata,
          })}\n\n`);
        }
      }
      
      res.end();
    } catch (error) {
      console.error("Error streaming message:", error);
      res.status(500).json({ error: "Failed to stream message" });
    }
  });

