  app.post("/api/privacy/recipients", requirePermission("security:write"), async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub || "current-user";
      
      const parsed = insertSharingRecipientSchema.safeParse({
        ...req.body,
        patientUserId: userId,
      });
      
      if (!parsed.success) {
        return res.status(400).json({ error: "Invalid recipient data", details: parsed.error.issues });
      }
      
      const recipient = await storage.createSharingRecipient(parsed.data);
      
      await storage.createConsentAuditLog({
        patientUserId: userId,
        recipientId: recipient.id,
        action: "grant",
        reason: "Created new sharing recipient",
        ipAddress: req.ip || undefined,
        userAgent: req.get("user-agent") || undefined,
      });
      
      res.status(201).json(recipient);
    } catch (error) {
      console.error("Error creating recipient:", error);
      res.status(500).json({ error: "Failed to create recipient" });
    }
  });

  // Update a sharing recipient
  app.patch("/api/privacy/recipients/:id", requirePermission("security:write"), async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub || "current-user";
      const { id } = req.params;
      
      const existing = await storage.getSharingRecipient(id);
      if (!existing || existing.patientUserId !== userId) {
        return res.status(404).json({ error: "Recipient not found" });
      }
      
      const updateSchema = insertSharingRecipientSchema.partial().omit({ patientUserId: true });
      const parsed = updateSchema.safeParse(req.body);
      
      if (!parsed.success) {
        return res.status(400).json({ error: "Invalid update data", details: parsed.error.issues });
      }
      
      const updated = await storage.updateSharingRecipient(id, parsed.data);
      
      await storage.createConsentAuditLog({
        patientUserId: userId,
        recipientId: id,
        action: "modify",
        reason: "Updated recipient details",
        ipAddress: req.ip || undefined,
        userAgent: req.get("user-agent") || undefined,
      });
      
      res.json(updated);
    } catch (error) {
      console.error("Error updating recipient:", error);
      res.status(500).json({ error: "Failed to update recipient" });
    }
  });

