  // Bulk update consents for a recipient
  app.put("/api/privacy/recipients/:id/consents", requirePermission("security:write"), async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub || "current-user";
      const { id } = req.params;
      const { consents } = req.body;
      
      const recipient = await storage.getSharingRecipient(id);
      if (!recipient || recipient.patientUserId !== userId) {
        return res.status(404).json({ error: "Recipient not found" });
      }
      
      if (!Array.isArray(consents)) {
        return res.status(400).json({ error: "Consents must be an array" });
      }
      
      const validConsents: { category: DataCategory; accessLevel: AccessLevel }[] = [];
      for (const consent of consents) {
        if (!dataCategories.includes(consent.category) || !accessLevels.includes(consent.accessLevel)) {
          return res.status(400).json({ error: `Invalid consent: ${JSON.stringify(consent)}` });
        }
        validConsents.push({ category: consent.category, accessLevel: consent.accessLevel });
      }
      
      const results = await storage.bulkUpdateConsents(userId, id, validConsents);
      
      await storage.createConsentAuditLog({
        patientUserId: userId,
        recipientId: id,
        action: "modify",
        reason: `Updated ${validConsents.length} consent settings`,
        ipAddress: req.ip || undefined,
        userAgent: req.get("user-agent") || undefined,
      });
      
      res.json(results);
    } catch (error) {
      console.error("Error updating consents:", error);
      res.status(500).json({ error: "Failed to update consents" });
    }
  });

