  // Generate a new de-identified dataset
  app.post("/api/research/datasets", requirePermission("records:export"), async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub || "current-user";
      
      const { method, purpose, categories, dateShiftDays, ageThreshold, zipCodeTruncation } = req.body;
      
      if (!method || !deidentificationMethods.includes(method)) {
        return res.status(400).json({ error: "Invalid de-identification method" });
      }
      
      if (!purpose || !researchPurposes.includes(purpose)) {
        return res.status(400).json({ error: "Invalid research purpose" });
      }
      
      if (!Array.isArray(categories) || categories.length === 0) {
        return res.status(400).json({ error: "At least one data category is required" });
      }
      
      for (const cat of categories) {
        if (!dataCategories.includes(cat)) {
          return res.status(400).json({ error: `Invalid data category: ${cat}` });
        }
      }
      
      const prefs = await storage.getResearchPreferences(userId);
      if (!prefs?.allowResearch) {
        return res.status(403).json({ error: "Research data sharing is not enabled. Please update your research preferences first." });
      }
      
      if (prefs.allowedPurposes && prefs.allowedPurposes.length > 0 && !prefs.allowedPurposes.includes(purpose)) {
        return res.status(403).json({ 
          error: `Research purpose "${purpose}" is not in your allowed purposes. Update your preferences to allow this purpose.` 
        });
      }
      
      if (prefs.preferredMethod && prefs.preferredMethod !== method) {
        return res.status(403).json({ 
          error: `Requested method "${method}" does not match your preferred method "${prefs.preferredMethod}". Update your preferences to use a different method.` 
        });
      }
      
      if (!prefs.allowMonetization && purpose === "health_economics") {
        return res.status(403).json({ 
          error: "Health economics research may involve monetization. Please enable monetization in your preferences or choose a different purpose." 
        });
      }
      
      const excludedCategories = prefs.excludedCategories || [];
      const filteredCategories = categories.filter((cat: DataCategory) => !excludedCategories.includes(cat));
      
      if (filteredCategories.length === 0) {
        return res.status(400).json({ 
          error: "All selected categories are excluded by your preferences. Update your preferences or select different categories." 
        });
      }
      
      if (filteredCategories.length < categories.length) {
        const excludedFromRequest = categories.filter((cat: DataCategory) => excludedCategories.includes(cat));
        console.log(`Excluded categories from request: ${excludedFromRequest.join(", ")}`);
      }
      
      const configId = `config-${Date.now()}`;
      
      const dataset = await generateDeidentifiedDataset(
        userId,
        configId,
        method,
        purpose,
        filteredCategories,
        {
          dateShiftDays: dateShiftDays || 0,
          ageThreshold: ageThreshold || 89,
          zipCodeTruncation: zipCodeTruncation || 3,
        }
      );
      
      res.json(dataset);
    } catch (error) {
      console.error("Error generating dataset:", error);
      res.status(500).json({ error: "Failed to generate dataset" });
    }
  });

