  // Download de-identified data from a dataset
  app.get("/api/research/datasets/:id/download", requirePermission("records:export"), async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub || "current-user";
      const { id } = req.params;
      const { format } = req.query;
      
      const dataset = await storage.getDeidentifiedDataset(id);
      
      if (!dataset || dataset.patientUserId !== userId) {
        return res.status(404).json({ error: "Dataset not found" });
      }
      
      if (dataset.status !== "completed") {
        return res.status(400).json({ error: "Dataset is not ready for download" });
      }
      
      if (dataset.expiresAt && new Date(dataset.expiresAt) < new Date()) {
        return res.status(410).json({ error: "Dataset has expired" });
      }
      
      const data = await getDeidentifiedData(id);
      
      await logDatasetDownload(
        id,
        userId,
        userId,
        "researcher",
        "Self-download",
        req.ip || undefined,
        req.get("user-agent") || undefined
      );
      
      if (format === "csv") {
        const csvHeader = Object.keys(data[0]?.data || {}).join(",");
        const csvRows = data.map(record => 
          Object.values(record.data as Record<string, unknown>).map(v => 
            typeof v === "string" ? `"${v.replace(/"/g, '""')}"` : v
          ).join(",")
        );
        const csv = [csvHeader, ...csvRows].join("\n");
        
        res.setHeader("Content-Type", "text/csv");
        res.setHeader("Content-Disposition", `attachment; filename="deidentified-${id}.csv"`);
        return res.send(csv);
      }
      
      res.setHeader("Content-Type", "application/json");
      res.setHeader("Content-Disposition", `attachment; filename="deidentified-${id}.json"`);
      res.json(data);
    } catch (error) {
      console.error("Error downloading dataset:", error);
      res.status(500).json({ error: "Failed to download dataset" });
    }
  });

