  // Get combined predictive insights (summary + risks + trends)
  app.get("/api/health-insights/predictive", async (req, res) => {
    try {
      const user = req.user as any;
      const patientId = user?.claims?.sub || "current-user";
      
      const [medications, allergies, conditions, labResults, wearableConnections, wearableData] = await Promise.all([
        storage.getMedicationsByPatient(patientId),
        storage.getAllergiesByPatient(patientId),
        storage.getProblemsByPatient(patientId),
        storage.getLabResultsByPatient(patientId),
        storage.getWearableConnections(patientId),
        storage.getWearableDataRecords(patientId),
      ]);
      
      const { analyzeHealthRisks, generateHealthTrendAnalysis } = await import("./predictive-health");
      
      const healthData = {
        medications,
        allergies,
        conditions,
        labResults,
        timelineEvents: [],
        goals: [],
      };
      
      const [riskAssessments, labTrends] = await Promise.all([
        Promise.resolve(analyzeHealthRisks(healthData)),
        generateHealthTrendAnalysis(labResults, 365),
      ]);

      // Calculate wearable metrics summary
      const now = new Date();
      const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
      const recentWearableData = wearableData.filter(d => new Date(d.recordedAt) >= sevenDaysAgo);
      
      const wearableSummary = {
        connectedDevices: wearableConnections.filter(c => c.status === "connected").length,
        totalDataPoints: recentWearableData.length,
        avgDailySteps: 0,
        avgHeartRate: 0,
        avgSleepHours: 0,
      };

      // Group data by date for proper daily averages
      const getDateKey = (dateStr: string) => new Date(dateStr).toISOString().split('T')[0];
      
      // Calculate daily averages from recent wearable data
      const stepsData = recentWearableData.filter(d => d.dataType === "steps");
      const heartRateData = recentWearableData.filter(d => d.dataType === "heart_rate");
      const sleepData = recentWearableData.filter(d => d.dataType === "sleep");

      // Steps: aggregate per day, then average across days
      if (stepsData.length > 0) {
        const stepsByDay: Record<string, number> = {};
        for (const d of stepsData) {
          const day = getDateKey(d.recordedAt);
          const steps = typeof d.value === 'number' ? d.value : 0;
          stepsByDay[day] = (stepsByDay[day] || 0) + steps;
        }
        const days = Object.keys(stepsByDay);
        const totalDailySteps = Object.values(stepsByDay).reduce((sum, v) => sum + v, 0);
        wearableSummary.avgDailySteps = days.length > 0 ? Math.round(totalDailySteps / days.length) : 0;
      }
      
      // Heart rate: average across all readings
      if (heartRateData.length > 0) {
        const totalHR = heartRateData.reduce((sum, d) => sum + (typeof d.value === 'number' ? d.value : 0), 0);
        wearableSummary.avgHeartRate = Math.round(totalHR / heartRateData.length);
      }
      
      // Sleep: average per night (aggregate per day first)
      if (sleepData.length > 0) {
        const sleepByNight: Record<string, number> = {};
        for (const d of sleepData) {
          const night = getDateKey(d.recordedAt);
          const hours = typeof d.value === 'object' && d.value && 'duration' in d.value 
            ? (d.value as any).duration 
            : (typeof d.value === 'number' ? d.value : 0);
          sleepByNight[night] = (sleepByNight[night] || 0) + hours;
        }
        const nights = Object.keys(sleepByNight);
        const totalSleep = Object.values(sleepByNight).reduce((sum, v) => sum + v, 0);
        wearableSummary.avgSleepHours = nights.length > 0 ? Math.round((totalSleep / nights.length) * 10) / 10 : 0;
      }
      
      res.json({
        patientId,
        generatedAt: new Date().toISOString(),
        riskAssessments,
        labTrends,
        dataSnapshot: {
          activeMedications: medications.filter(m => m.status === "active").length,
          activeConditions: conditions.filter(c => c.status === "active").length,
          recentLabTests: labResults.length,
          allergies: allergies.length,
          connectedDevices: wearableSummary.connectedDevices,
        },
        wearableSummary,
      });
    } catch (error) {
      console.error("Error fetching predictive insights:", error);
      res.status(500).json({ error: "Failed to fetch predictive insights" });
    }
  });

