  app.post("/api/gamification/record-adherence", async (req, res) => {
    try {
      const user = req.user as any;
      const patientId = user?.claims?.sub || "current-user";
      const { medicationName, action } = req.body;

      const { createPointTransaction, calculateLevel, createInitialPlayerStats, updateStreak } = await import("./gamification-engine");

      let stats = await storage.getPlayerStats(patientId);
      if (!stats) {
        stats = createInitialPlayerStats(patientId);
        await storage.createPlayerStats(stats);
      }

      const pointsForAction = action === "taken" ? 10 : action === "on_time" ? 15 : 5;
      const transaction = createPointTransaction(patientId, pointsForAction, "goal_progress", `Medication adherence: ${medicationName || "medication"} ${action}`);
      await storage.createPointTransaction(transaction);

      stats.totalPoints += pointsForAction;
      stats.weeklyPoints = (stats.weeklyPoints || 0) + pointsForAction;

      const streaks = await storage.getStreakRecords(patientId);
      let medStreak = streaks.find(s => s.streakType === "medication_adherence");
      if (!medStreak) {
        medStreak = {
          id: `streak-med-${patientId}`,
          patientId,
          streakType: "medication_adherence",
          currentCount: 0,
          longestCount: 0,
          lastActivityDate: new Date().toISOString(),
          isActive: true,
          startedAt: new Date().toISOString(),
          metadata: {},
        };
      }

      const updatedStreak = updateStreak(medStreak, "medication_adherence");
      await storage.updatePlayerStats(patientId, stats);

      const levelInfo = calculateLevel(stats.totalPoints);

      res.json({
        pointsEarned: pointsForAction,
        totalPoints: stats.totalPoints,
        currentStreak: updatedStreak.currentCount,
        longestStreak: updatedStreak.longestCount,
        level: levelInfo.level,
        levelName: levelInfo.levelName,
        message: `+${pointsForAction} points for ${action === "taken" ? "taking" : "logging"} ${medicationName || "medication"}!`,
      });
    } catch (error) {
      console.error("Error recording adherence:", error);
      res.status(500).json({ error: "Failed to record adherence" });
    }
  });

