  const aiAssistantAnalysisCache = new Map<string, { result: any; generatedAt: string; expiresAt: string }>();

  app.post("/api/provider/portal/ai-assistant/analyze", requireRole("provider", "admin"), async (req, res) => {
    try {
      const { patientIds, analysisType = "comprehensive" } = req.body;
      const targetPatientIds = Array.isArray(patientIds) && patientIds.length > 0 
        ? patientIds 
        : ["patient-1", "patient-2", "patient-3"];
      
      const patientSummaries = targetPatientIds.map((pid) => ({
        patientId: pid,
        vitalCount: Math.floor(20 + Math.random() * 30),
        abnormalVitals: Math.floor(Math.random() * 5),
        labCount: Math.floor(10 + Math.random() * 20),
        abnormalLabs: Math.floor(Math.random() * 4),
        medicationCount: Math.floor(3 + Math.random() * 5),
        adherenceRate: Math.round(70 + Math.random() * 25),
        activeConditions: ["Type 2 Diabetes", "Hypertension", "Hyperlipidemia"].slice(0, Math.floor(1 + Math.random() * 3)),
      }));

      const prompt = `You are an AI clinical assistant in a provider portal. Analyze the following patient panel data and generate proactive clinical insights.

CRITICAL COMPLIANCE:
- Use "may suggest" or "consider" language only - NEVER prescribe or diagnose
- Every finding must include "Consult with treating physician" caveat
- This is NO-CDS compliant - for informational awareness only

Patient Panel Data:
${JSON.stringify(patientSummaries, null, 2)}

Analysis Type: ${analysisType}

Generate a JSON response with this structure:
{
  "panelOverview": {
    "totalPatients": number,
    "patientsNeedingAttention": number,
    "overallAdherenceAvg": number,
    "criticalFindings": number
  },
  "flaggedPatients": [
    {
      "patientId": "string",
      "priority": "critical" | "high" | "moderate" | "low",
      "flags": [
        {
          "type": "adherence" | "vitals" | "labs" | "medication" | "general",
          "severity": "critical" | "warning" | "info",
          "title": "Brief title",
          "description": "Detailed observation",
          "suggestedActions": ["Action 1", "Action 2"],
          "evidence": ["Supporting data point"]
        }
      ],
      "summary": "One-line patient summary"
    }
  ],
  "panelInsights": [
    {
      "category": "trend" | "risk" | "opportunity" | "compliance",
      "title": "string",
      "description": "string",
      "affectedPatients": number,
      "recommendation": "string"
    }
  ],
  "disclaimer": "This analysis is for informational purposes only and does not constitute medical advice, diagnosis, or treatment. Always consult with the treating physician."
}`;

      const response = await openai.chat.completions.create({
        model: "gpt-4o-mini",
        messages: [{ role: "user", content: prompt }],
        response_format: { type: "json_object" },
        max_completion_tokens: 4096,
      });

      const analysis = JSON.parse(response.choices[0]?.message?.content || "{}");
      analysis.generatedAt = new Date().toISOString();
      analysis.analysisId = `ai-assist-${Date.now()}`;

      const cacheKey = targetPatientIds.sort().join(",");
      aiAssistantAnalysisCache.set(cacheKey, {
        result: analysis,
        generatedAt: analysis.generatedAt,
        expiresAt: new Date(Date.now() + 30 * 60 * 1000).toISOString(),
      });

      res.json(analysis);
    } catch (error) {
      console.error("Error in AI assistant analysis:", error);
      res.status(500).json({ error: "Failed to generate AI analysis" });
    }
  });

