  // ============================================
  // ONBOARDING API
  // ============================================

  // Get onboarding status
  app.get("/api/onboarding/status", async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub || "current-user";
      const status = await storage.getOnboardingStatus(userId);
      res.json(status || { hasCompletedOnboarding: false, completedSteps: [] });
    } catch (error) {
      console.error("Error fetching onboarding status:", error);
      res.status(500).json({ error: "Failed to fetch onboarding status" });
    }
  });

  // Complete onboarding
  app.post("/api/onboarding/complete", async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub || "current-user";
      const { completedSteps, goals } = req.body;

      // Validate completedSteps
      const { z } = await import("zod");
      const onboardingCompleteSchema = z.object({
        completedSteps: z.array(z.string()).default([]),
        goals: z.array(z.object({
          category: z.enum(["weight", "exercise", "nutrition", "medication", "mental_health", "sleep", "other"]).optional(),
          title: z.string().min(1),
          description: z.string().optional(),
          targetValue: z.string().optional(),
          unit: z.string().optional(),
        })).optional(),
      });

      const validation = onboardingCompleteSchema.safeParse(req.body);
      if (!validation.success) {
        return res.status(400).json({ error: "Invalid request data", details: validation.error.errors });
      }

      const validatedData = validation.data;

      // Complete onboarding
      const status = await storage.completeOnboarding(userId, validatedData.completedSteps);

      // Clear any saved mobile onboarding progress so the table doesn't
      // hold stale per-user rows after setup is finished, and so a user
      // who restarts onboarding begins with a clean slate.
      try {
        const { clearMobileOnboardingProgress } = await import("./storage/onboarding-cleanup");
        await clearMobileOnboardingProgress(userId);
      } catch (cleanupErr) {
        console.warn("[Onboarding] Failed to clear mobile_onboarding_progress row:", (cleanupErr as Error).message);
      }

      // Automatically assign 'patient' role to new users completing onboarding
      const existingUser = await storage.getUser(userId);
      if (existingUser && (!existingUser.role || existingUser.role !== 'patient')) {
        await storage.updateUserRole(userId, 'patient');
      }

      // Create health goals if provided
      if (validatedData.goals && Array.isArray(validatedData.goals)) {
        for (const goal of validatedData.goals) {
          if (goal.title) {
            await storage.createHealthGoal({
              patientId: userId,
              title: goal.title,
              description: goal.description || "",
              category: goal.category || "other",
              targetValue: goal.targetValue || "",
              currentValue: "",
              unit: goal.unit || "",
              startDate: new Date().toISOString(),
              targetDate: undefined,
              status: "active",
              progress: 0,
              notes: "",
            });
          }
        }
      }

      // Create welcome notification for new patient
      try {
        await storage.createSecurityNotification({
          userId,
          type: "info",
          title: "Welcome to Tabula Medica!",
          message: "Your account is set up. Visit your Personal Health Dashboard to view your health information and get personalized insights.",
          importance: "low",
          actionUrl: "/personal-health",
        });
      } catch (notifyError) {
        console.log("Could not create welcome notification:", notifyError);
      }

      res.json({ success: true, status, redirectTo: "/personal-health" });
    } catch (error) {
      console.error("Error completing onboarding:", error);
      res.status(500).json({ error: "Failed to complete onboarding" });
    }
  });

  // Complete patient registration with full form data
  app.post("/api/patient-onboarding/complete", async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub || "current-user";
      
      // Validate request body with Zod
      const { z } = await import("zod");
      const patientRegistrationSchema = z.object({
        formData: z.object({
          personalInfo: z.object({
            firstName: z.string().min(1).optional(),
            lastName: z.string().min(1).optional(),
            dateOfBirth: z.string().optional(),
            gender: z.string().optional(),
            email: z.string().email().optional().or(z.literal("")),
            phone: z.string().optional(),
            address: z.string().optional(),
            city: z.string().optional(),
            state: z.string().optional(),
            zipCode: z.string().optional(),
            preferredLanguage: z.string().optional(),
          }).optional(),
          medicalHistory: z.object({
            conditions: z.array(z.string()).optional(),
            surgeries: z.array(z.object({ name: z.string(), date: z.string() })).optional(),
            familyHistory: z.array(z.object({ condition: z.string(), relation: z.string() })).optional(),
          }).optional(),
          medications: z.array(z.object({
            name: z.string(),
            dosage: z.string().optional(),
            frequency: z.string().optional(),
          })).optional(),
          allergies: z.array(z.object({
            allergen: z.string(),
            reaction: z.string().optional(),
            severity: z.enum(["mild", "moderate", "severe"]).optional(),
          })).optional(),
          emergencyContacts: z.array(z.object({
            name: z.string(),
            relationship: z.string(),
            phone: z.string(),
            email: z.string().optional(),
          })).optional(),
          consent: z.object({
            termsAccepted: z.boolean(),
            privacyPolicyAccepted: z.boolean(),
            dataProcessingConsent: z.boolean(),
            communicationConsent: z.boolean().optional(),
          }).optional(),
        }).optional(),
        completedSteps: z.array(z.string()).optional(),
      });

      const validation = patientRegistrationSchema.safeParse(req.body);
      if (!validation.success) {
        return res.status(400).json({ error: "Invalid registration data", details: validation.error.errors });
      }

      const { formData, completedSteps } = validation.data;

      // Create or update onboarding session with form data
      let session = await storage.getOnboardingSessionByUser(userId);
      if (!session) {
        session = await storage.createOnboardingSession({
          userId,
          currentStep: "complete",
          completedSteps: completedSteps || [],
          formData: formData || {},
        });
      } else {
        session = await storage.updateOnboardingSession(session.id, {
          formData: { ...session.formData, ...formData },
          completedSteps: completedSteps || session.completedSteps,
          currentStep: "complete",
          isComplete: true,
          completedAt: new Date().toISOString(),
        });
      }

      // Complete the onboarding session
      await storage.completeOnboardingSession(session!.id);

      // Automatically assign 'patient' role
      const existingUser = await storage.getUser(userId);
      if (existingUser && (!existingUser.role || existingUser.role !== 'patient')) {
        await storage.updateUserRole(userId, 'patient');
      }

      // Create allergies from form data
      if (formData?.allergies && Array.isArray(formData.allergies)) {
        for (const allergy of formData.allergies) {
          if (allergy.allergen) {
            await storage.createAllergy({
              patientId: userId,
              allergen: allergy.allergen,
              reaction: allergy.reaction || "Unknown",
              severity: allergy.severity || "moderate",
              status: "active",
            });
          }
        }
      }

      // Create medications from form data
      if (formData?.medications && Array.isArray(formData.medications)) {
        for (const med of formData.medications) {
          if (med.name) {
            await storage.createMedication({
              patientId: userId,
              name: med.name,
              dosage: med.dosage || "",
              frequency: med.frequency || "as needed",
              status: "active",
              prescribedDate: new Date().toISOString(),
            });
          }
        }
      }

      // Create welcome notification
      try {
        await storage.createSecurityNotification({
          userId,
          type: "info",
          title: "Registration Complete!",
          message: "Welcome to Tabula Medica! Your health profile has been created. Explore your Personal Health Dashboard to see your health information and get personalized insights.",
          importance: "medium",
          actionUrl: "/personal-health",
        });
      } catch (notifyError) {
        console.log("Could not create welcome notification:", notifyError);
      }

      // Log the registration for HIPAA compliance
      await storage.createSecurityAuditLog({
        userId,
        eventType: "registration_complete",
        description: "Patient completed registration and onboarding",
        ipAddress: (req.headers["x-forwarded-for"] as string)?.split(",")[0]?.trim() || req.socket?.remoteAddress || "Unknown",
        userAgent: req.headers["user-agent"] || "Unknown",
        metadata: { completedSteps },
      });

      res.json({ 
        success: true, 
        redirectTo: "/personal-health",
        message: "Registration complete! Welcome to Tabula Medica."
      });
    } catch (error) {
      console.error("Error completing patient registration:", error);
      res.status(500).json({ error: "Failed to complete registration" });
    }
  });

