  // Get patient adherence data for provider medication management
  app.get("/api/provider/patient-adherence", requireRole("provider", "admin"), async (req, res) => {
    try {
      const patients = await storage.getPatients();
      const adherenceData = await Promise.all(
        patients.slice(0, 20).map(async (patient) => {
          const stats = await storage.getAdherenceStatistics(patient.id, undefined);
          const medications = await storage.getMedicationsByPatient(patient.id);
          const activeMeds = medications.filter(m => m.status === "active");
          const logs = await storage.getAdherenceLogs(patient.id);
          
          // Calculate risk level based on adherence
          let riskLevel: "low" | "medium" | "high" = "low";
          if (stats.adherenceRate < 60) riskLevel = "high";
          else if (stats.adherenceRate < 80) riskLevel = "medium";
          
          // Find last activity from actual logs
          const lastLog = logs.length > 0 ? logs.sort((a, b) => 
            new Date(b.scheduledTime).getTime() - new Date(a.scheduledTime).getTime()
          )[0] : null;
          
          return {
            patientId: patient.id,
            patientName: `${patient.firstName} ${patient.lastName}`,
            adherenceRate: stats.adherenceRate,
            streak: stats.streak,
            totalMedications: activeMeds.length,
            missedDoses: stats.totalMissed,
            lastActivity: lastLog?.scheduledTime || stats.lastRecordedAt || null,
            riskLevel,
            medicationCount: activeMeds.length,
          };
        })
      );
      res.json(adherenceData);
    } catch (error) {
      console.error("Error fetching patient adherence data:", error);
      res.status(500).json({ error: "Failed to fetch patient adherence data" });
    }
  });

