  // ==================== Provider Portal Patient Trends Routes ====================

  // Get patient health trends with vitals, labs, and AI insights
  app.get("/api/provider/portal/patient-trends", requireRole("provider", "admin"), async (req, res) => {
    try {
      const { patientId, timeRange = "30d" } = req.query;
      
      if (!patientId || typeof patientId !== "string") {
        return res.status(400).json({ error: "patientId is required" });
      }

      // Validate timeRange
      const validRanges = ["7d", "30d", "90d", "1y"];
      if (typeof timeRange !== "string" || !validRanges.includes(timeRange)) {
        return res.status(400).json({ error: "Invalid timeRange. Must be 7d, 30d, 90d, or 1y" });
      }

      const userId = (req as any).user?.claims?.sub || "provider-default";
      const { logPhiAccess } = await import("./security/hipaa-audit");

      // Log HIPAA PHI access
      await logPhiAccess({
        userId,
        action: "read",
        resourceType: "patient_trends",
        resourceId: patientId,
        details: JSON.stringify({ timeRange, dataType: "vitals_labs_insights" }),
        timestamp: new Date().toISOString(),
      });

      // Generate mock patient trends data
      const now = new Date();
      const daysBack = timeRange === "7d" ? 7 : timeRange === "30d" ? 30 : timeRange === "90d" ? 90 : 365;
      
      // Mock vitals trends (Blood Pressure, Heart Rate, Blood Glucose)
      const vitalsTrends = {
        bloodPressure: {
          metric: "Blood Pressure (mmHg)",
          dataPoints: Array.from({ length: Math.min(daysBack, 30) }, (_, i) => ({
            date: new Date(now.getTime() - (daysBack - i) * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
            systolic: Math.round(110 + Math.random() * 30),
            diastolic: Math.round(70 + Math.random() * 20),
            status: "normal"
          })),
          trend: "stable",
          latest: { systolic: 128, diastolic: 82 }
        },
        heartRate: {
          metric: "Heart Rate (bpm)",
          dataPoints: Array.from({ length: Math.min(daysBack, 30) }, (_, i) => ({
            date: new Date(now.getTime() - (daysBack - i) * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
            value: Math.round(60 + Math.random() * 30),
            status: "normal"
          })),
          trend: "stable",
          latest: 72
        },
        bloodGlucose: {
          metric: "Blood Glucose (mg/dL)",
          dataPoints: Array.from({ length: Math.min(daysBack, 30) }, (_, i) => ({
            date: new Date(now.getTime() - (daysBack - i) * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
            value: Math.round(80 + Math.random() * 50),
            status: i % 5 === 0 ? "elevated" : "normal"
          })),
          trend: "slight_increase",
          latest: 105
        }
      };

      // Mock lab trends
      const labsTrends = [
        {
          testName: "Hemoglobin A1C",
          unit: "%",
          referenceRange: "<5.7",
          dataPoints: Array.from({ length: Math.min(daysBack / 30, 4) }, (_, i) => ({
            date: new Date(now.getTime() - (4 - i) * 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
            value: 6.2 + Math.random() * 0.5,
            status: "elevated"
          })),
          latest: 6.5,
          trend: "increasing"
        },
        {
          testName: "Total Cholesterol",
          unit: "mg/dL",
          referenceRange: "<200",
          dataPoints: Array.from({ length: Math.min(daysBack / 30, 4) }, (_, i) => ({
            date: new Date(now.getTime() - (4 - i) * 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
            value: 180 + Math.random() * 40,
            status: "normal"
          })),
          latest: 195,
          trend: "stable"
        },
        {
          testName: "Creatinine",
          unit: "mg/dL",
          referenceRange: "0.6-1.2",
          dataPoints: Array.from({ length: Math.min(daysBack / 30, 4) }, (_, i) => ({
            date: new Date(now.getTime() - (4 - i) * 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
            value: 0.8 + Math.random() * 0.3,
            status: "normal"
          })),
          latest: 0.95,
          trend: "stable"
        }
      ];

      // Mock AI insights
      const aiInsights = {
        summary: "Patient shows stable vital trends with slight elevation in blood glucose levels. Recent lab results within acceptable ranges.",
        alerts: [
          {
            severity: "warning",
            message: "Blood glucose trending upward. Consider diet review and exercise optimization.",
            metric: "bloodGlucose"
          }
        ],
        recommendations: [
          "Continue current medication regimen",
          "Increase physical activity to 150 minutes per week",
          "Monitor fasting glucose levels daily",
          "Schedule endocrinology follow-up within 3 months"
        ],
        riskScore: 0.35,
        riskLevel: "moderate"
      };

      res.json({
        patientId,
        timeRange,
        generatedAt: new Date().toISOString(),
        vitals: vitalsTrends,
        labs: labsTrends,
        aiInsights
      });

    } catch (error) {
      console.error("Error fetching patient trends:", error);
      res.status(500).json({ error: "Failed to fetch patient trends" });
    }
  });

  // ==================== Provider Portal Audit Logs Routes ====================

  // Get provider audit log entries
  app.get("/api/provider/portal/audit-logs", requireRole("provider", "admin"), async (req, res) => {
    try {
      const { action, range = "7d", q } = req.query;

      // Validate range parameter
      const validRanges = ["1d", "7d", "30d", "90d"];
      if (range && (typeof range !== "string" || !validRanges.includes(range))) {
        return res.status(400).json({ error: "Invalid range. Must be 1d, 7d, 30d, or 90d" });
      }

      const userId = (req as any).user?.claims?.sub || "provider-default";
      const rangeStr = typeof range === "string" ? range : "7d";
      const { logPhiAccess } = await import("./security/hipaa-audit");

      // Log HIPAA PHI access
      await logPhiAccess({
        userId,
        action: "read",
        resourceType: "audit_logs",
        resourceId: `audit_logs_${rangeStr}`,
        details: JSON.stringify({ 
          filterAction: action || "all",
          searchQuery: q || null,
          timeRange: rangeStr 
        }),
        timestamp: new Date().toISOString(),
      });

      // Generate mock audit log entries
      const daysBack = rangeStr === "1d" ? 1 : rangeStr === "7d" ? 7 : rangeStr === "30d" ? 30 : 90;
      const now = new Date();

      const actions = ["view", "export", "update", "share", "message"];
      const mockLogs = Array.from({ length: 25 }, (_, i) => {
        const logAction = actions[Math.floor(Math.random() * actions.length)];
        const timestamp = new Date(now.getTime() - Math.random() * daysBack * 24 * 60 * 60 * 1000);
        
        return {
          id: `audit_${i + 1}`,
          timestamp: timestamp.toISOString(),
          providerName: ["Dr. Sarah Johnson", "Dr. Michael Chen", "Dr. Emily Rodriguez", "Dr. James Wilson"][Math.floor(Math.random() * 4)],
          providerId: ["provider_001", "provider_002", "provider_003", "provider_004"][Math.floor(Math.random() * 4)],
          action: logAction,
          patientName: ["John Smith", "Mary Johnson", "Robert Davis", "Patricia Brown", "Michael Wilson"][Math.floor(Math.random() * 5)],
          patientId: `patient_${String(i + 1).padStart(3, '0')}`,
          resource: {
            type: logAction === "view" ? "medical_record" : logAction === "export" ? "patient_data" : logAction === "update" ? "medication_list" : "patient_share",
            name: logAction === "view" ? "Health Records" : logAction === "export" ? "Patient Data Export" : logAction === "update" ? "Medication List Update" : "Share to Care Team"
          },
          ipAddress: `192.168.${Math.floor(Math.random() * 255)}.${Math.floor(Math.random() * 255)}`,
          userAgent: "Mozilla/5.0 (Chrome)",
          phiAccessed: true,
          phiTypes: logAction === "view" ? ["vitals", "labs", "medications"] : logAction === "export" ? ["medical_history", "lab_results"] : logAction === "update" ? ["medications"] : ["patient_contact"],
          status: Math.random() > 0.95 ? "failed" : "success",
          duration: `${Math.floor(Math.random() * 10) + 1}s`
        };
      });

      // Filter by action if provided
      let filteredLogs = mockLogs;
      if (action && typeof action === "string" && actions.includes(action)) {
        filteredLogs = mockLogs.filter(log => log.action === action);
      }

      // Filter by search query if provided
      if (q && typeof q === "string") {
        const searchTerm = q.toLowerCase();
        filteredLogs = filteredLogs.filter(log => 
          log.providerName.toLowerCase().includes(searchTerm) ||
          log.patientName.toLowerCase().includes(searchTerm) ||
          log.action.toLowerCase().includes(searchTerm)
        );
      }

      // Sort by timestamp descending
      filteredLogs.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());

      // Calculate summary statistics
      const summary = {
        totalEntries: filteredLogs.length,
        timeRange: rangeStr,
        actionBreakdown: actions.reduce((acc, act) => {
          acc[act] = filteredLogs.filter(log => log.action === act).length;
          return acc;
        }, {} as Record<string, number>),
        phiAccessCount: filteredLogs.filter(log => log.phiAccessed).length,
        failedActions: filteredLogs.filter(log => log.status === "failed").length
      };

      res.json({
        summary,
        filters: {
          action: action || null,
          timeRange: rangeStr,
          searchQuery: q || null
        },
        entries: filteredLogs.slice(0, 100), // Return first 100 entries
        generatedAt: new Date().toISOString()
      });

    } catch (error) {
      console.error("Error fetching audit logs:", error);
      res.status(500).json({ error: "Failed to fetch audit logs" });
    }
  });

