  // Create new prescription (e-prescribe)
  app.post("/api/provider/portal/prescriptions", requireRole("provider", "admin"), async (req, res) => {
    try {
      const userId = (req as any).user?.claims?.sub || "provider-default";
      const { logger } = await import("./security/phi-safe-logger");
      const { insertPrescriptionSchema } = await import("@shared/schema");

      // Validate request body
      const parseResult = insertPrescriptionSchema.safeParse(req.body);
      if (!parseResult.success) {
        return res.status(400).json({ 
          error: "Invalid prescription data", 
          details: parseResult.error.errors 
        });
      }

      const prescriptionData = parseResult.data;

      // Log HIPAA PHI access for creating prescription
      logger.phiAccess(userId, prescriptionData.patientId, "Prescription", "Provider creating new e-prescription");
      logger.audit("CREATE_PRESCRIPTION", userId, "Prescription", {
        patientId: prescriptionData.patientId,
        medication: prescriptionData.medicationName,
        isControlledSubstance: prescriptionData.isControlledSubstance,
      });

      // Generate new prescription
      const prescribedDate = new Date().toISOString().split("T")[0];
      const expirationDate = new Date();
      expirationDate.setFullYear(expirationDate.getFullYear() + 1);

      const newPrescription = {
        id: `rx_${randomUUID().substring(0, 8)}`,
        ...prescriptionData,
        status: "pending" as const,
        prescribedDate,
        expirationDate: expirationDate.toISOString().split("T")[0],
        refillsRemaining: prescriptionData.refillsAuthorized,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      };

      res.status(201).json({
        prescription: newPrescription,
        message: "Prescription created successfully",
      });

    } catch (error) {
      console.error("Error creating prescription:", error);
      res.status(500).json({ error: "Failed to create prescription" });
    }
  });

