  // Generate personalized health tips using AI
  app.post("/api/health-tips/generate", async (req, res) => {
    try {
      const user = req.user as any;
      const patientId = user?.claims?.sub || "sarah-unified-001";
      
      // Get patient's conditions and medications for context
      const patient = await storage.getUnifiedPatient(patientId);
      const medications = await storage.getMedicationsByPatient(patientId);
      const conditions = await storage.getConditions(patientId);
      
      const OpenAI = (await import("openai")).default;
      const openai = new OpenAI();
      
      const context = {
        medications: medications.map(m => m.name).slice(0, 5),
        conditions: conditions.map(c => c.name).slice(0, 5),
      };
      
      const aiResponse = await openai.chat.completions.create({
        model: "gpt-4o",
        messages: [
          {
            role: "system",
            content: `You are a health education assistant. Generate personalized, actionable health tips based on the patient's medications and conditions. Tips should be educational and empowering, never medical advice. Format as JSON array with objects containing: title, content, summary, category (one of: medication, nutrition, exercise, sleep, mental_health, chronic_disease, prevention, lifestyle), readTimeMinutes.`
          },
          {
            role: "user",
            content: `Generate 3 personalized health tips for a patient with:
Medications: ${context.medications.join(", ") || "None specified"}
Conditions: ${context.conditions.join(", ") || "None specified"}

Return JSON array of tips.`
          }
        ],
        response_format: { type: "json_object" },
        max_tokens: 1000,
      });
      
      const content = aiResponse.choices[0]?.message?.content;
      const parsedTips = content ? JSON.parse(content) : { tips: [] };
      const generatedTips = parsedTips.tips || [];
      
      // Save and deliver tips
      const deliveredTips = [];
      for (const tipData of generatedTips) {
        const tip = await storage.createHealthTip({
          title: tipData.title,
          content: tipData.content,
          summary: tipData.summary,
          category: tipData.category || "lifestyle",
          format: "tip",
          targetConditions: context.conditions,
          targetMedications: context.medications,
          readTimeMinutes: tipData.readTimeMinutes || 2,
          isAiGenerated: true,
          aiPromptContext: `Generated for patient with medications: ${context.medications.join(", ")}`,
          priority: 80,
        });
        
        const patientTip = await storage.createPatientHealthTip({
          patientId,
          healthTipId: tip.id,
          reason: "Personalized based on your health profile",
          relevanceScore: 85,
        });
        
        deliveredTips.push({ ...patientTip, healthTip: tip });
      }
      
      res.json(deliveredTips);
    } catch (error) {
      console.error("Error generating health tips:", error);
      res.status(500).json({ error: "Failed to generate health tips" });
    }
  });

