  app.post("/api/triage/sessions/:id/analyze", async (req, res) => {
    try {
      const session = await storage.getTriageSession(req.params.id);
      if (!session) {
        return res.status(404).json({ error: "Triage session not found" });
      }

      const patientMedications = await storage.getMedicationsByPatient(session.patientId);
      const patientConditions = await storage.getProblemsByPatient(session.patientId);
      const patientAllergies = await storage.getAllergiesByPatient(session.patientId);

      const prompt = `You are an AI medical triage assistant. Analyze the following patient symptoms and provide a comprehensive assessment. This is for educational purposes only and is NOT a medical diagnosis.

PATIENT CONTEXT:
- Current Medications: ${patientMedications.map((m: Medication) => m.name).join(", ") || "None listed"}
- Known Conditions: ${patientConditions.map((c: Problem) => c.name).join(", ") || "None listed"}
- Known Allergies: ${patientAllergies.map((a: Allergy) => a.name).join(", ") || "None listed"}
- Additional Risk Factors: ${session.riskFactors?.join(", ") || "None specified"}

CHIEF COMPLAINT: ${session.chiefComplaint}

SYMPTOMS REPORTED:
${session.symptoms.map(s => `- ${s.name}
  Location: ${s.bodyRegion}
  Severity: ${s.severity}
  Duration: ${s.duration}
  Worsening: ${s.worsening ? "Yes" : "No"}
  Interferes with daily life: ${s.interferesWithDailyLife ? "Yes" : "No"}
  ${s.description ? `Additional details: ${s.description}` : ""}`).join("\n\n")}

${session.additionalContext ? `ADDITIONAL CONTEXT: ${session.additionalContext}` : ""}

${session.vitalSigns ? `VITAL SIGNS:
- Temperature: ${session.vitalSigns.temperature || "Not provided"}
- Heart Rate: ${session.vitalSigns.heartRate || "Not provided"}
- Blood Pressure: ${session.vitalSigns.bloodPressure || "Not provided"}
- Oxygen Saturation: ${session.vitalSigns.oxygenSaturation || "Not provided"}` : ""}

Provide your analysis in the following JSON format:
{
  "summary": "A brief patient-friendly summary of the assessment",
  "urgencyLevel": "emergency|urgent|soon|routine|self_care",
  "urgencyReasoning": "Explanation for the urgency level",
  "potentialConditions": [
    {
      "name": "Condition name",
      "likelihood": "possible|likely|less_likely",
      "description": "Brief patient-friendly description",
      "commonSymptoms": ["symptom1", "symptom2"],
      "whenToSeekCare": "Guidance on when to seek care"
    }
  ],
  "recommendations": [
    {
      "type": "emergency_call|emergency_room|urgent_care|schedule_appointment|telehealth|specialist_referral|self_care|monitor",
      "urgency": "emergency|urgent|soon|routine|self_care",
      "title": "Recommendation title",
      "description": "Detailed description",
      "timeframe": "When to act",
      "specialistType": "Type of specialist if applicable",
      "selfCareInstructions": ["instruction1", "instruction2"],
      "warningSignsToWatch": ["sign1", "sign2"]
    }
  ],
  "questionsToAsk": ["Question to gather more info"],
  "confidence": 0.75
}

IMPORTANT: 
1. Always err on the side of caution - recommend seeking medical care for concerning symptoms
2. Consider drug interactions and existing conditions
3. Provide actionable next steps
4. Include clear warning signs that would require immediate care
5. This is educational only - always include a disclaimer`;

      const completion = await openai.chat.completions.create({
        model: "gpt-4o",
        messages: [
          { role: "system", content: "You are a medical triage AI assistant. Provide helpful, accurate, and safe guidance while always recommending professional medical consultation for concerning symptoms. Never provide definitive diagnoses." },
          { role: "user", content: prompt }
        ],
        response_format: { type: "json_object" },
        temperature: 0.3,
      });

      const analysisText = completion.choices[0]?.message?.content || "{}";
      let analysis;
      try {
        analysis = JSON.parse(analysisText);
      } catch {
        analysis = {
          summary: "Unable to analyze symptoms. Please consult a healthcare provider.",
          urgencyLevel: "soon",
          urgencyReasoning: "AI analysis could not be completed",
          potentialConditions: [],
          recommendations: [{
            type: "schedule_appointment",
            urgency: "soon",
            title: "Consult Healthcare Provider",
            description: "Please schedule an appointment with your healthcare provider to discuss your symptoms.",
            timeframe: "Within the next few days"
          }],
          confidence: 0
        };
      }

      const aiAnalysis = {
        ...analysis,
        disclaimer: "This assessment is for informational and educational purposes only. It is not a substitute for professional medical advice, diagnosis, or treatment. Always seek the advice of your physician or other qualified health provider with any questions you may have regarding a medical condition. If you think you may have a medical emergency, call your doctor or emergency services immediately.",
        analyzedAt: new Date().toISOString(),
      };

      const updatedSession = await storage.updateTriageSession(session.id, {
        aiAnalysis,
        status: "completed",
      });

      if (aiAnalysis.urgencyLevel === "emergency" || aiAnalysis.urgencyLevel === "urgent") {
        await storage.createProviderAlert({
          patientId: session.patientId,
          patientName: "Patient",
          providerId: "system",
          providerName: "AI Triage System",
          alertType: "symptom_escalation",
          severity: aiAnalysis.urgencyLevel === "emergency" ? "critical" : "high",
          title: `Urgent Triage Alert: ${session.chiefComplaint}`,
          description: aiAnalysis.summary,
          details: {
            sourceType: "ai_analysis",
            sourceId: session.id,
            relatedData: { chiefComplaint: session.chiefComplaint, symptoms: session.symptoms },
          },
          recommendedActions: aiAnalysis.recommendations.map((r: any) => r.title),
          aiAnalysis: JSON.stringify(aiAnalysis),
        });
      }

      res.json(updatedSession);
    } catch (error) {
      console.error("Error analyzing triage session:", error);
      res.status(500).json({ error: "Failed to analyze symptoms" });
    }
  });

