  // Submit quiz attempt
  app.post("/api/patients/:patientId/education/quizzes/:quizId/submit", async (req, res) => {
    try {
      const { patientId, quizId } = req.params;
      const { answers, timeSpent } = req.body;

      const quiz = await storage.getEducationQuiz(quizId);
      if (!quiz) {
        return res.status(404).json({ error: "Quiz not found" });
      }

      const gradedAnswers = answers.map((a: { questionId: string; answer: string }) => {
        const question = quiz.questions.find(q => q.id === a.questionId);
        return {
          questionId: a.questionId,
          answer: a.answer,
          isCorrect: question?.correctAnswer === a.answer,
        };
      });

      const correctCount = gradedAnswers.filter((a: { isCorrect: boolean }) => a.isCorrect).length;
      const totalPoints = gradedAnswers.reduce((sum: number, a: { questionId: string; isCorrect: boolean }) => {
        const question = quiz.questions.find(q => q.id === a.questionId);
        return sum + (a.isCorrect ? (question?.points || 10) : 0);
      }, 0);
      const score = Math.round((correctCount / quiz.questions.length) * 100);
      const passed = score >= quiz.passingScore;

      const attempt = {
        id: randomUUID(),
        patientId,
        quizId,
        quiz,
        answers: gradedAnswers,
        score,
        totalPoints: passed ? totalPoints + quiz.pointsReward : totalPoints,
        passed,
        timeSpent: timeSpent || 0,
        completedAt: new Date().toISOString(),
      };

      await storage.createQuizAttempt(attempt);

      const today = new Date().toISOString().split("T")[0];
      const streak = await storage.getLearningStreak(patientId);
      if (!streak || streak.lastActivityDate.split("T")[0] !== today) {
        const isConsecutive = streak && 
          new Date(streak.lastActivityDate).getTime() > Date.now() - 2 * 86400000;
        const newStreak = isConsecutive ? (streak?.currentStreak || 0) + 1 : 1;
        await storage.updateLearningStreak(patientId, {
          currentStreak: newStreak,
          longestStreak: Math.max(newStreak, streak?.longestStreak || 0),
          lastActivityDate: new Date().toISOString(),
          totalDaysActive: (streak?.totalDaysActive || 0) + 1,
        });
      }

      res.status(201).json({
        attempt,
        feedback: {
          passed,
          score,
          totalPoints: attempt.totalPoints,
          correctAnswers: correctCount,
          totalQuestions: quiz.questions.length,
          explanations: quiz.questions.map(q => ({
            questionId: q.id,
            explanation: q.explanation,
            wasCorrect: gradedAnswers.find((a: { questionId: string }) => a.questionId === q.id)?.isCorrect,
          })),
        },
      });
    } catch (error) {
      console.error("Error submitting quiz:", error);
      res.status(500).json({ error: "Failed to submit quiz" });
    }
  });

