  // ============================================
  // TELEHEALTH VIDEO CONSULTATION ROUTES
  // ============================================

  // WebSocket server for real-time video signaling with session authentication
  const wss = new WebSocketServer({ server: httpServer, path: '/ws' });
  const rooms = new Map<string, Set<{ ws: WebSocket; userId: string }>>();
  const roomSessionCache = new Map<string, { patientId: string; providerId: string }>();

  wss.on('connection', (ws: WebSocket, req) => {
    let currentRoom: string | null = null;
    let authenticatedUserId: string | null = null;
    let isAuthorized = false;

    ws.on('message', async (message: string) => {
      try {
        const data = JSON.parse(message.toString());
        
        switch (data.type) {
          case 'join':
            const requestedRoomId = data.roomId;
            const claimedUserId = data.userId;
            
            // Validate room exists and get session details
            let sessionInfo = roomSessionCache.get(requestedRoomId);
            if (!sessionInfo) {
              const session = await storage.getTelehealthSessionByRoom(requestedRoomId);
              if (!session) {
                ws.send(JSON.stringify({ type: 'error', message: 'Invalid room' }));
                ws.close();
                return;
              }
              // Only allow joining scheduled, waiting, or in-progress sessions
              if (!['scheduled', 'waiting', 'in_progress'].includes(session.status)) {
                ws.send(JSON.stringify({ type: 'error', message: 'Session not available' }));
                ws.close();
                return;
              }
              sessionInfo = { patientId: session.patientId, providerId: session.providerId };
              roomSessionCache.set(requestedRoomId, sessionInfo);
            }
            
            // Verify caller is authorized (is either the patient or provider for this session)
            const isPatient = claimedUserId.startsWith(`patient-${sessionInfo.patientId}`);
            const isProvider = claimedUserId.startsWith(`provider-${sessionInfo.providerId}`);
            if (!isPatient && !isProvider) {
              ws.send(JSON.stringify({ type: 'error', message: 'Unauthorized access' }));
              ws.close();
              return;
            }
            
            authenticatedUserId = claimedUserId;
            isAuthorized = true;
            currentRoom = requestedRoomId;
            
            if (!rooms.has(currentRoom)) {
              rooms.set(currentRoom, new Set());
            }
            rooms.get(currentRoom)!.add({ ws, userId: authenticatedUserId });
            
            // Send room joined confirmation
            ws.send(JSON.stringify({ type: 'room-joined', roomId: currentRoom }));
            
            // Notify others in room
            rooms.get(currentRoom)!.forEach(client => {
              if (client.ws !== ws && client.ws.readyState === WebSocket.OPEN) {
                client.ws.send(JSON.stringify({ type: 'user-joined', userId: authenticatedUserId }));
              }
            });
            break;

          case 'offer':
          case 'answer':
          case 'ice-candidate':
            // Only relay if user is authorized and in a room
            if (!isAuthorized || !currentRoom) {
              ws.send(JSON.stringify({ type: 'error', message: 'Not authorized' }));
              return;
            }
            // Relay signaling messages to other peers in the room
            if (rooms.has(currentRoom)) {
              rooms.get(currentRoom)!.forEach(client => {
                if (client.ws !== ws && client.ws.readyState === WebSocket.OPEN) {
                  client.ws.send(JSON.stringify(data));
                }
              });
            }
            break;

          case 'leave':
            if (!isAuthorized) return;
            if (currentRoom && rooms.has(currentRoom)) {
              // Find and remove client from room
              const roomClients = rooms.get(currentRoom)!;
              for (const client of roomClients) {
                if (client.ws === ws) {
                  roomClients.delete(client);
                  break;
                }
              }
              // Notify others
              roomClients.forEach(client => {
                if (client.ws.readyState === WebSocket.OPEN) {
                  client.ws.send(JSON.stringify({ type: 'user-left', userId: authenticatedUserId }));
                }
              });
            }
            currentRoom = null;
            isAuthorized = false;
            break;

          case 'chat':
            if (!isAuthorized || !currentRoom) {
              ws.send(JSON.stringify({ type: 'error', message: 'Not authorized' }));
              return;
            }
            if (rooms.has(currentRoom)) {
              const chatData = { ...data, userId: authenticatedUserId };
              rooms.get(currentRoom)!.forEach(client => {
                if (client.ws.readyState === WebSocket.OPEN) {
                  client.ws.send(JSON.stringify(chatData));
                }
              });
            }
            break;

          case 'key-exchange':
            if (!isAuthorized || !currentRoom) {
              ws.send(JSON.stringify({ type: 'error', message: 'Not authorized' }));
              return;
            }
            if (rooms.has(currentRoom)) {
              rooms.get(currentRoom)!.forEach(client => {
                if (client.ws !== ws && client.ws.readyState === WebSocket.OPEN) {
                  client.ws.send(JSON.stringify({
                    type: 'key-exchange',
                    publicKey: data.publicKey,
                    userId: authenticatedUserId,
                  }));
                }
              });
            }
            break;

          case 'encrypted-chat':
            if (!isAuthorized || !currentRoom) {
              ws.send(JSON.stringify({ type: 'error', message: 'Not authorized' }));
              return;
            }
            if (rooms.has(currentRoom)) {
              const encChatData = {
                type: 'encrypted-chat',
                id: `msg-${Date.now()}-${Math.random().toString(36).substr(2, 6)}`,
                userId: authenticatedUserId,
                userName: data.userName,
                senderRole: data.senderRole,
                ciphertext: data.ciphertext,
                iv: data.iv,
                timestamp: new Date().toISOString(),
              };
              rooms.get(currentRoom)!.forEach(client => {
                if (client.ws.readyState === WebSocket.OPEN) {
                  client.ws.send(JSON.stringify(encChatData));
                }
              });
            }
            break;

          case 'screen-share-start':
          case 'screen-share-stop':
            if (!isAuthorized || !currentRoom) return;
            if (rooms.has(currentRoom)) {
              rooms.get(currentRoom)!.forEach(client => {
                if (client.ws !== ws && client.ws.readyState === WebSocket.OPEN) {
                  client.ws.send(JSON.stringify({
                    type: data.type,
                    userId: authenticatedUserId,
                  }));
                }
              });
            }
            break;

          case 'recording-consent-request':
          case 'recording-consent-response':
          case 'recording-started':
          case 'recording-stopped':
            if (!isAuthorized || !currentRoom) return;
            if (rooms.has(currentRoom)) {
              rooms.get(currentRoom)!.forEach(client => {
                if (client.ws !== ws && client.ws.readyState === WebSocket.OPEN) {
                  client.ws.send(JSON.stringify({
                    ...data,
                    userId: authenticatedUserId,
                  }));
                }
              });
            }
            break;
        }
      } catch (error) {
        console.error('WebSocket message error:', error);
      }
    });

    ws.on('close', () => {
      if (currentRoom && rooms.has(currentRoom)) {
        const roomClients = rooms.get(currentRoom)!;
        for (const client of roomClients) {
          if (client.ws === ws) {
            roomClients.delete(client);
            // Notify others of disconnect
            roomClients.forEach(c => {
              if (c.ws.readyState === WebSocket.OPEN) {
                c.ws.send(JSON.stringify({ type: 'user-left', userId: authenticatedUserId }));
              }
            });
            break;
          }
        }
        if (roomClients.size === 0) {
          rooms.delete(currentRoom);
          roomSessionCache.delete(currentRoom);
        }
      }
    });
  });

