  // Universal search endpoint with AI natural language processing
  app.post("/api/search", async (req, res) => {
    try {
      const { query, patientId, filters, isVoiceQuery, queryLanguage } = req.body;
      const startTime = Date.now();

      // Parse natural language query using AI
      let interpretedQuery = query;
      let nlpFilters: SearchFilters = filters || {};

      try {
        const nlpResponse = await openai.chat.completions.create({
          model: "gpt-4o",
          messages: [
            {
              role: "system",
              content: `You are a medical search query interpreter. Parse the user's search query and extract:
1. The main search terms (what they're looking for)
2. Any date ranges mentioned
3. Any specific data types (medications, conditions, lab results, etc.)
4. Any provider names mentioned

Return JSON with:
{
  "searchTerms": "main keywords to search",
  "dataTypes": ["conditions", "medications", etc] or null,
  "dateFrom": "ISO date string" or null,
  "dateTo": "ISO date string" or null,
  "providers": ["provider names"] or null
}

Available data types: ${searchableDataTypes.join(", ")}`,
            },
            {
              role: "user",
              content: query,
            },
          ],
          response_format: { type: "json_object" },
          max_completion_tokens: 200,
        });

        const parsed = JSON.parse(nlpResponse.choices[0]?.message?.content || "{}");
        interpretedQuery = parsed.searchTerms || query;
        if (parsed.dataTypes) nlpFilters.dataTypes = parsed.dataTypes;
        if (parsed.dateFrom) nlpFilters.dateFrom = parsed.dateFrom;
        if (parsed.dateTo) nlpFilters.dateTo = parsed.dateTo;
        if (parsed.providers) nlpFilters.providers = parsed.providers;
      } catch (nlpError) {
        console.error("NLP parsing error, using raw query:", nlpError);
      }

      // Merge parsed filters with provided filters
      const mergedFilters: SearchFilters = {
        ...nlpFilters,
        ...filters,
      };

      // Perform search
      const results = await storage.searchPatientData(interpretedQuery, patientId, mergedFilters);
      const executionTimeMs = Date.now() - startTime;

      // Save search query for history
      const userId = (req as any).user?.claims?.sub || "anonymous";
      const searchQuery: SearchQuery = {
        id: randomUUID(),
        patientId,
        userId,
        query,
        queryLanguage: queryLanguage || "en",
        isVoiceQuery: isVoiceQuery || false,
        naturalLanguageIntent: interpretedQuery,
        filters: mergedFilters,
        resultsCount: results.length,
        executionTimeMs,
        createdAt: new Date().toISOString(),
      };
      await storage.saveSearchQuery(searchQuery);

      // Generate facets for filtering
      const facets = {
        dataTypes: [] as { type: string; count: number }[],
        dateRanges: [] as { range: string; count: number }[],
        providers: [] as { name: string; count: number }[],
      };

      const dataTypeCounts: Record<string, number> = {};
      const providerCounts: Record<string, number> = {};

      results.forEach(r => {
        dataTypeCounts[r.dataType] = (dataTypeCounts[r.dataType] || 0) + 1;
        if (r.provider) {
          providerCounts[r.provider] = (providerCounts[r.provider] || 0) + 1;
        }
      });

      facets.dataTypes = Object.entries(dataTypeCounts).map(([type, count]) => ({ type, count }));
      facets.providers = Object.entries(providerCounts).map(([name, count]) => ({ name, count }));

      // Generate search suggestions
      const suggestions: string[] = [];
      if (results.length === 0) {
        suggestions.push("Try using different keywords");
        suggestions.push("Remove some filters to broaden the search");
      }

      res.json({
        query,
        interpretedQuery,
        totalResults: results.length,
        executionTimeMs,
        results,
        facets,
        suggestions,
      });
    } catch (error) {
      console.error("Search error:", error);
      res.status(500).json({ error: "Search failed" });
    }
  });

