  // ============================================
  // AMBIENT ENCOUNTER NOTES
  // Patient records a doctor visit; we transcribe + structure it.
  // CRITICAL: audio buffer is held in memory only and NEVER written
  // to disk, object storage, a database, or any log line. Only the
  // text transcript + SOAP + action items leave this handler.
  // ============================================
  {
    const multer = (await import("multer")).default;
    const audioUpload = multer({
      storage: multer.memoryStorage(),
      limits: { fileSize: 50 * 1024 * 1024 }, // 50 MB cap (~30 min @ 64kbps opus)
    });

    app.post(
      "/api/ambient-encounter/process",
      requireRole("patient", "caregiver", "admin", "support", "provider"),
      audioUpload.single("audio"),
      async (req, res) => {
        try {
          if (!req.file || !req.file.buffer || req.file.buffer.length === 0) {
            return res.status(400).json({ error: "Missing audio upload" });
          }
          const mime = req.file.mimetype || "audio/webm";
          const language = typeof req.body?.language === "string" ? req.body.language : undefined;

          const { ambientEncounterService } = await import("./ambient-encounter-service");
          const result = await ambientEncounterService.processEncounter(
            req.file.buffer,
            mime,
            language,
          );

          // Drop reference to the audio buffer ASAP. Multer's memoryStorage
          // means no disk write occurred. The request object goes out of
          // scope after the response is sent and GC reclaims the buffer.
          // Do NOT add any code here that persists req.file.buffer.
          (req.file as any).buffer = null;

          res.json(result);
        } catch (error: any) {
          console.error("Ambient encounter processing error:", error?.message || error);
          res.status(500).json({
            error: error?.message || "Failed to process encounter",
          });
        }
      },
    );
  }

  // ============================================
  // CHART INTELLIGENCE - USPSTF CARE GAP DETECTION
  // Stateless evaluator: caller submits patient demographics + conditions
  // + medications + lastScreenings; service returns per-rule status.
  // No CDS — informational only. Patient-facing endpoint.
  // ============================================
  app.post(
    "/api/chart-intelligence/care-gaps",
    requireRole("patient", "caregiver", "admin", "support", "provider"),
    async (req, res) => {
      try {
        const { careGapsService } = await import("./care-gaps-service");
        const body = req.body || {};

        const patient = body.patient ?? body;
        if (!patient || typeof patient !== "object") {
          return res.status(400).json({ error: "Missing patient payload" });
        }

        const age = Number(patient.age);
        const biologicalSex = patient.biologicalSex ?? patient.sex ?? patient.gender;
        if (!Number.isFinite(age) || age < 0 || age > 130) {
          return res.status(400).json({ error: "Valid age (0–130) is required" });
        }
        if (biologicalSex !== "female" && biologicalSex !== "male") {
          return res.status(400).json({
            error:
              "biologicalSex must be 'female' or 'male'. This field reflects anatomy for screening eligibility (mammography, cervical screening) and is distinct from gender identity.",
          });
        }

        const evaluation = careGapsService.evaluate({
          age,
          biologicalSex,
          conditions: Array.isArray(patient.conditions) ? patient.conditions : [],
          medications: Array.isArray(patient.medications) ? patient.medications : [],
          bmi: patient.bmi != null ? Number(patient.bmi) : undefined,
          smokingPackYears: patient.smokingPackYears != null ? Number(patient.smokingPackYears) : undefined,
          smokingStatus: patient.smokingStatus,
          yearsQuit: patient.yearsQuit != null ? Number(patient.yearsQuit) : undefined,
          cvdRiskFactorCount: patient.cvdRiskFactorCount != null ? Number(patient.cvdRiskFactorCount) : undefined,
          lastScreenings:
            patient.lastScreenings && typeof patient.lastScreenings === "object"
              ? patient.lastScreenings
              : {},
          surgicalHistory: Array.isArray(patient.surgicalHistory) ? patient.surgicalHistory : [],
        });

        res.json(evaluation);
      } catch (error) {
        console.error("Error evaluating care gaps:", error);
        res.status(500).json({ error: "Failed to evaluate care gaps" });
      }
    },
  );

