  // Chat with assistant (streaming)
  app.post("/api/assistant/chat/:patientId/stream", requireRole("patient", "caregiver", "admin", "support"), async (req, res) => {
    try {
      const { chatWithAssistant, analyzeSentiment } = await import("./services/patientAssistant");
      const { messages } = req.body;
      if (!messages || !Array.isArray(messages)) {
        return res.status(400).json({ error: "Messages array is required" });
      }

      res.setHeader("Content-Type", "text/event-stream");
      res.setHeader("Cache-Control", "no-cache");
      res.setHeader("Connection", "keep-alive");

      req.on("close", () => {
        res.end();
      });

      const lastUserMessage = [...messages].reverse().find((m: any) => m.role === "user");
      
      const sentimentPromise = lastUserMessage 
        ? analyzeSentiment(lastUserMessage.content).catch((err) => {
            console.error("Sentiment analysis error (non-blocking):", err);
            return { sentiment: "neutral" as const, confidence: 0.5, emotionalCues: [], suggestedTone: "friendly and supportive" };
          })
        : Promise.resolve(null);

      const stream = await chatWithAssistant(req.params.patientId, messages, true) as AsyncIterable<string>;
      
      for await (const chunk of stream) {
        if (res.writableEnded) break;
        res.write(`data: ${JSON.stringify({ content: chunk })}\n\n`);
      }
      
      if (!res.writableEnded) {
        try {
          const sentiment = await sentimentPromise;
          if (sentiment) {
            res.write(`data: ${JSON.stringify({ sentiment })}\n\n`);
          }
        } catch (err) {
          console.error("Sentiment finalization error:", err);
        }
        res.write(`data: [DONE]\n\n`);
        res.end();
      }
    } catch (error) {
      console.error("Error streaming chat:", error);
      if (!res.headersSent) {
        res.status(500).json({ error: "Failed to stream chat response" });
      }
    }
  });

