  // Get export requests with filters
  app.get("/api/export-control/requests", async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub;

      if (!userId) {
        return res.status(401).json({ error: "Authentication required" });
      }

      const role = await getUserRole(userId);
      
      let filters: { requesterId?: string; patientId?: string; status?: any } = {};
      
      if (role !== "admin") {
        // Non-admin users can only see their own requests
        filters.requesterId = userId;
      } else {
        // Admin can filter by any criteria
        if (req.query.requesterId) filters.requesterId = String(req.query.requesterId);
        if (req.query.patientId) filters.patientId = String(req.query.patientId);
        if (req.query.status) filters.status = String(req.query.status);
      }
      
      // Admins with no query filters are explicitly allowed to read all requests.
      const allowUnscoped = role === "admin";
      const requests = await storage.getExportRequests(filters, allowUnscoped);
      res.json(requests);
    } catch (error) {
      console.error("Error fetching export requests:", error);
      res.status(500).json({ error: "Failed to fetch export requests" });
    }
  });

  // Create export request
  app.post("/api/export-control/requests", isAuthenticated, async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub as string;
      const role: UserRole = await getUserRole(userId);
      
      const policy = await storage.getExportPolicyForRole(role);
      if (!policy) {
        return res.status(403).json({ error: "No export policy available for your role" });
      }
      
      // Check if requested format is allowed
      if (!policy.allowedFormats.includes(req.body.format)) {
        return res.status(403).json({ 
          error: "Export format not allowed",
          allowedFormats: policy.allowedFormats,
        });
      }
      
      // Check if requested data types are allowed
      const invalidDataTypes = req.body.dataTypes?.filter((dt: string) => 
        !policy.allowedDataTypes.includes("all") && !policy.allowedDataTypes.includes(dt as any)
      );
      if (invalidDataTypes?.length > 0) {
        return res.status(403).json({ 
          error: "Some data types are not allowed for export",
          invalidDataTypes,
          allowedDataTypes: policy.allowedDataTypes,
        });
      }

      // Patients can only request their own data; providers/admins may specify a patientId
      const patientId = (role === "patient") ? userId : (req.body.patientId || userId);
      
      const status = policy.requiresApproval ? "pending" : "approved";
      const expiresAt = status === "approved" 
        ? new Date(Date.now() + policy.retentionDays * 24 * 60 * 60 * 1000)
        : undefined;
      
      const request = await storage.createExportRequest({
        requesterId: userId,
        requesterRole: role,
        patientId,
        policyId: policy.id,
        format: req.body.format,
        dataTypes: req.body.dataTypes || ["all"],
        dateRangeStart: req.body.dateRangeStart ? new Date(req.body.dateRangeStart) : undefined,
        dateRangeEnd: req.body.dateRangeEnd ? new Date(req.body.dateRangeEnd) : undefined,
        purpose: req.body.purpose,
        status,
        downloadCount: 0,
        maxDownloads: 5,
        expiresAt,
        ipAddress: req.ip || "unknown",
        userAgent: req.get("user-agent") || "unknown",
        metadata: {},
      });
      
      await storage.createExportAuditEntry({
        exportRequestId: request.id,
        action: "requested",
        performedBy: userId,
        performedByRole: role,
        ipAddress: req.ip || "unknown",
        userAgent: req.get("user-agent") || "unknown",
        details: `Export request created for patient ${patientId}`,
      });
      
      logPhiAccess({
        action: "export_request_created",
        resourceType: "export_request",
        resourceId: request.id,
        userId,
        accessReason: req.body.purpose,
        accessType: "create",
        phiFields: ["patientId", ...req.body.dataTypes],
      });
      
      res.status(201).json(request);
    } catch (error) {
      console.error("Error creating export request:", error);
      res.status(500).json({ error: "Failed to create export request" });
    }
  });

