  // Download export (track download)
  app.post("/api/export-control/requests/:id/download", isAuthenticated, async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub as string;
      
      const request = await storage.getExportRequest(req.params.id);
      if (!request) {
        return res.status(404).json({ error: "Export request not found" });
      }
      
      if (request.status !== "approved" && request.status !== "completed") {
        return res.status(403).json({ error: "Export not approved" });
      }
      
      if (request.requesterId !== userId) {
        const role = await getUserRole(userId);
        if (role !== "admin") {
          return res.status(403).json({ error: "Not authorized to download this export" });
        }
      }
      
      if (request.expiresAt && new Date(request.expiresAt) < new Date()) {
        return res.status(410).json({ error: "Export has expired" });
      }
      
      if (request.downloadCount >= request.maxDownloads) {
        return res.status(403).json({ error: "Maximum download limit reached" });
      }
      
      const updated = await storage.incrementExportDownloadCount(req.params.id);
      
      await storage.createExportAuditEntry({
        exportRequestId: req.params.id,
        action: "downloaded",
        performedBy: userId,
        performedByRole: request.requesterRole,
        ipAddress: req.ip || "unknown",
        userAgent: req.get("user-agent") || "unknown",
        details: `Export downloaded (${updated?.downloadCount}/${request.maxDownloads})`,
      });
      
      logPhiAccess({
        action: "export_downloaded",
        resourceType: "export_request",
        resourceId: req.params.id,
        userId,
        accessReason: "Export file download",
        accessType: "read",
        phiFields: ["patientId", ...request.dataTypes],
      });
      
      // Return success - actual file would be generated here
      res.json({ 
        success: true,
        message: "Export ready for download",
        downloadCount: updated?.downloadCount,
        maxDownloads: request.maxDownloads,
        expiresAt: request.expiresAt,
      });
    } catch (error) {
      console.error("Error processing export download:", error);
      res.status(500).json({ error: "Failed to process export download" });
    }
  });

