  // Get health summary for quick view
  // PHI protection: Same security model as main dashboard
  app.get("/api/personal-health/summary", async (req, res) => {
    try {
      const user = (req as any).user;
      const isAuthenticated = !!user?.claims?.sub;
      
      let patientId: string;
      let userId: string;
      
      if (isAuthenticated) {
        userId = user.claims.sub;
        patientId = userId;
      } else {
        userId = "system_user";
        patientId = "sample_patient";
      }
      
      // Log PHI access for HIPAA compliance
      logPhiAccess({
        userId,
        patientId,
        resourceType: "HealthSummary",
        action: "read",
        details: isAuthenticated ? "Authenticated health summary view" : "Sample mode summary view",
      });
      
      const vitals = await storage.getVitalsByPatient(patientId);
      const medications = await storage.getMedicationsByPatient(patientId);
      const goals = await storage.getHealthGoals(patientId);
      const appointments = await storage.getUpcomingAppointments();
      
      res.json({
        patientId,
        quickStats: {
          vitalsRecorded: vitals.length,
          activeMedications: medications.filter(m => m.status === "active").length,
          activeGoals: goals.filter(g => g.status === "active" || g.status === "in_progress").length,
          upcomingAppointments: appointments.filter(a => a.patientId === patientId).length,
        },
        alerts: [
          { type: "reminder", message: "Medication due in 2 hours", priority: "medium" },
          { type: "appointment", message: "Checkup tomorrow at 10 AM", priority: "low" },
        ],
      });
    } catch (error) {
      console.error("Error fetching health summary:", error);
      res.status(500).json({ error: "Failed to fetch health summary" });
    }
  });

  // ==================== Consolidated Health Records Endpoints ====================
  console.log("[Routes] Consolidated Health Records routes registered at /api/health-records");

  // Zod schemas for health record operations
  const insertPersonalMetricSchema = z.object({
    metricType: z.enum(["weight", "blood_pressure_systolic", "blood_pressure_diastolic", "heart_rate", "blood_glucose", "steps", "sleep_hours", "water_intake", "mood", "pain_level", "energy_level", "stress_level", "exercise_minutes", "custom"]),
    customName: z.string().optional(),
    value: z.number(),
    unit: z.string().min(1),
    notes: z.string().optional(),
    source: z.enum(["manual", "device", "ehr"]).default("manual"),
    deviceId: z.string().optional(),
    recordedAt: z.string().optional(),
  });

  const insertMetricGoalSchema = z.object({
    metricType: z.enum(["weight", "blood_pressure_systolic", "blood_pressure_diastolic", "heart_rate", "blood_glucose", "steps", "sleep_hours", "water_intake", "mood", "pain_level", "energy_level", "stress_level", "exercise_minutes", "custom"]),
    targetValue: z.number(),
    comparison: z.enum(["less_than", "greater_than", "between", "equals"]),
    targetValueMax: z.number().optional(),
    unit: z.string().min(1),
    frequency: z.enum(["daily", "weekly", "monthly"]).default("daily"),
    isActive: z.boolean().default(true),
  });

  const insertShareSchema = z.object({
    recipientType: z.enum(["provider", "caregiver", "family", "care_team"]),
    recipientId: z.string().min(1),
    recipientName: z.string().min(1),
    dataCategories: z.array(z.string()).min(1),
    accessLevel: z.enum(["view", "view_and_download"]).default("view"),
    validFrom: z.string().optional(),
    validUntil: z.string().optional(),
  });

  // Zod schemas for patient health goals
  const insertPatientHealthGoalSchema = z.object({
    goalType: z.enum([
      "weight_loss", "weight_gain", "blood_pressure", "blood_sugar", "cholesterol",
      "exercise_frequency", "exercise_duration", "steps", "sleep_hours", "water_intake",
      "medication_adherence", "diet", "smoking_cessation", "stress_reduction", "custom"
    ]),
    title: z.string().min(1, "Goal title is required"),
    description: z.string().optional(),
    targetValue: z.number(),
    targetValueMax: z.number().optional(),
    currentValue: z.number().optional(),
    unit: z.string().min(1),
    comparison: z.enum(["less_than", "greater_than", "between", "equals", "at_least"]),
    startDate: z.string().optional(),
    targetDate: z.string().optional(),
    frequency: z.enum(["daily", "weekly", "monthly", "quarterly"]).default("weekly"),
    linkedResources: z.array(z.object({
      type: z.enum(["medication", "condition", "lab_result", "care_plan"]),
      resourceId: z.string(),
      resourceName: z.string(),
      reason: z.string().optional(),
    })).default([]),
    reminderEnabled: z.boolean().default(false),
    reminderFrequency: z.enum(["daily", "weekly"]).optional(),
  });

  const insertPatientGoalProgressSchema = z.object({
    goalId: z.string().min(1),
    value: z.number(),
    notes: z.string().optional(),
    recordedAt: z.string().optional(),
    source: z.enum(["manual", "device", "ehr"]).default("manual"),
  });

  const insertPatientGoalShareSchema = z.object({
    goalId: z.string().min(1),
    recipientType: z.enum(["provider", "caregiver", "family"]),
    recipientId: z.string().min(1),
    recipientName: z.string().min(1),
    canComment: z.boolean().default(false),
  });

  // Get consolidated health records (all data in one view)
  app.get("/api/health-records/consolidated", isAuthenticated, async (req, res) => {
    try {
      const patientId = (req as any).user?.claims?.sub;
      if (!patientId) return res.status(401).json({ error: "Unauthorized" });

      // Log PHI access
      logPhiAccess({
        userId: patientId,
        patientId,
        resourceType: "ConsolidatedHealthRecords",
        action: "read",
        details: "Patient accessed consolidated health records",
      });

      const [medications, allergies, vitals, records, goals, documents, problems] = await Promise.all([
        storage.getMedicationsByPatient(patientId),
        storage.getAllergiesByPatient(patientId),
        storage.getVitalsByPatient(patientId),
        storage.getHealthRecords(patientId),
        storage.getHealthGoals(patientId),
        storage.getUploadedDocuments(patientId),
        storage.getPatientProblems(patientId),
      ]);

      // Categorize records
      const labResults = records.filter(r => r.type === "lab_result");
      const immunizations = records.filter(r => r.type === "immunization");
      const procedures = records.filter(r => r.type === "procedure");
      const encounters = records.filter(r => r.type === "encounter");

      res.json({
        patientId,
        lastUpdated: new Date().toISOString(),
        summary: {
          totalMedications: medications.filter(m => m.status === "active").length,
          totalConditions: problems.filter(p => p.status === "active").length,
          totalAllergies: allergies.length,
          recentLabResults: labResults.slice(0, 5).length,
          totalDocuments: documents.length,
          activeGoals: goals.filter(g => g.status === "active" || g.status === "in_progress").length,
        },
        medications: medications.filter(m => m.status === "active").slice(0, 20).map(m => ({
          id: m.id,
          name: m.name,
          dosage: m.dosage,
          frequency: m.frequency,
          prescribedBy: m.prescribedBy,
          startDate: m.startDate,
          instructions: m.instructions,
          refillsRemaining: m.refillsRemaining,
        })),
        conditions: problems.filter(p => p.status === "active").map(p => ({
          id: p.id,
          name: p.name,
          code: p.code,
          onsetDate: p.onsetDate,
          status: p.status,
          severity: p.severity,
        })),
        allergies: allergies.map(a => ({
          id: a.id,
          allergen: a.allergen,
          reaction: a.reaction,
          severity: a.severity,
          verifiedBy: a.verifiedBy,
        })),
        vitals: vitals.slice(0, 20).map(v => ({
          id: v.id,
          type: v.type,
          value: v.value,
          unit: v.unit,
          recordedAt: v.recordedAt,
          source: v.source,
        })),
        labResults: labResults.slice(0, 10).map(l => ({
          id: l.id,
          name: l.description,
          date: l.date,
          provider: l.provider,
          status: "final",
        })),
        immunizations: immunizations.slice(0, 10).map(i => ({
          id: i.id,
          name: i.description,
          date: i.date,
          provider: i.provider,
        })),
        documents: documents.slice(0, 20).map(d => ({
          id: d.id,
          documentType: d.documentType,
          fileName: d.originalFileName,
          uploadedAt: d.uploadedAt,
          isVerified: d.isVerified,
        })),
      });
    } catch (error) {
      console.error("Error fetching consolidated health records:", error);
      res.status(500).json({ error: "Failed to fetch health records" });
    }
  });

  // Personal health metrics CRUD
  app.get("/api/health-records/metrics", isAuthenticated, async (req, res) => {
    try {
      const patientId = (req as any).user?.claims?.sub;
      if (!patientId) return res.status(401).json({ error: "Unauthorized" });
      const { metricType, startDate, endDate } = req.query;
      
      const metrics = await storage.getPersonalHealthMetrics(
        patientId,
        metricType as string,
        startDate as string,
        endDate as string
      );
      res.json(metrics);
    } catch (error) {
      console.error("Error fetching personal metrics:", error);
      res.status(500).json({ error: "Failed to fetch personal metrics" });
    }
  });

  app.post("/api/health-records/metrics", isAuthenticated, async (req, res) => {
    try {
      const patientId = (req as any).user?.claims?.sub;
      if (!patientId) return res.status(401).json({ error: "Unauthorized" });
      
      const parseResult = insertPersonalMetricSchema.safeParse(req.body);
      if (!parseResult.success) {
        return res.status(400).json({ error: "Invalid request", details: parseResult.error.format() });
      }
      
      // Log PHI access for HIPAA compliance
      logPhiAccess({
        userId: patientId,
        patientId,
        resourceType: "PersonalHealthMetric",
        action: "create",
        details: `Patient created personal health metric: ${parseResult.data.metricType}`,
      });
      
      const metric = await storage.createPersonalHealthMetric({
        patientId,
        ...parseResult.data,
      });
      res.status(201).json(metric);
    } catch (error) {
      console.error("Error creating personal metric:", error);
      res.status(500).json({ error: "Failed to create personal metric" });
    }
  });

  app.delete("/api/health-records/metrics/:id", isAuthenticated, async (req, res) => {
    try {
      const patientId = (req as any).user?.claims?.sub;
      if (!patientId) return res.status(401).json({ error: "Unauthorized" });
      const metric = await storage.getPersonalHealthMetric(req.params.id);
      if (!metric || metric.patientId !== patientId) {
        return res.status(404).json({ error: "Metric not found" });
      }
      await storage.deletePersonalHealthMetric(req.params.id, patientId);
      res.json({ success: true });
    } catch (error) {
      console.error("Error deleting personal metric:", error);
      res.status(500).json({ error: "Failed to delete personal metric" });
    }
  });

