  app.get("/api/health-records/export", isAuthenticated, async (req, res) => {
    try {
      const patientId = (req as any).user?.claims?.sub;
      if (!patientId) return res.status(401).json({ error: "Unauthorized" });
      const { format = "json" } = req.query;

      // Log PHI access
      logPhiAccess({
        userId: patientId,
        patientId,
        resourceType: "HealthRecordsExport",
        action: "export",
        details: `Patient exported health records in ${format} format`,
      });

      const [medications, allergies, vitals, records, problems, documents] = await Promise.all([
        storage.getMedicationsByPatient(patientId),
        storage.getAllergiesByPatient(patientId),
        storage.getVitalsByPatient(patientId),
        storage.getHealthRecords(patientId),
        storage.getPatientProblems(patientId),
        storage.getUploadedDocuments(patientId),
      ]);

      const labResults = records.filter(r => r.type === "lab_result");
      const immunizations = records.filter(r => r.type === "immunization");

      const exportData = {
        exportedAt: new Date().toISOString(),
        patientId,
        format,
        sections: {
          medications: {
            count: medications.length,
            active: medications.filter(m => m.status === "active"),
          },
          conditions: {
            count: problems.length,
            active: problems.filter(p => p.status === "active"),
          },
          allergies: {
            count: allergies.length,
            data: allergies,
          },
          vitals: {
            count: vitals.length,
            recent: vitals.slice(0, 50),
          },
          labResults: {
            count: labResults.length,
            data: labResults.slice(0, 50),
          },
          immunizations: {
            count: immunizations.length,
            data: immunizations,
          },
          documents: {
            count: documents.length,
            metadata: documents.map(d => ({
              id: d.id,
              documentType: d.documentType,
              fileName: d.originalFileName,
              uploadedAt: d.uploadedAt,
            })),
          },
        },
      };

      if (format === "json") {
        res.json(exportData);
      } else {
        // For PDF format, return JSON with PDF generation instructions
        res.json({
          ...exportData,
          pdfGenerationSupported: true,
          message: "Use /api/health-records/export/pdf for PDF download",
        });
      }
    } catch (error) {
      console.error("Error exporting health records:", error);
      res.status(500).json({ error: "Failed to export health records" });
    }
  });

