  // Import the AI document insights service
  const aiDocInsights = await import("./services/aiDocumentInsights");

  // Zod schema for document analysis request
  const documentAnalysisRequestSchema = z.object({
    documentType: z.enum(["pdf", "ccd", "lab_report", "imaging_report", "clinical_note", "discharge_summary"]),
    title: z.string().min(1, "Title is required"),
    content: z.string().min(1, "Content is required"),
    date: z.string().optional(),
    provider: z.string().optional(),
    patientId: z.string().optional(),
    patientContext: z.object({
      age: z.number().optional(),
      conditions: z.array(z.string()).optional(),
      medications: z.array(z.string()).optional(),
      allergies: z.array(z.string()).optional(),
    }).optional(),
  });

  // Analyze a document and generate AI insights
  app.post("/api/documents/:documentId/analyze", requireRole("patient", "provider", "admin"), async (req, res) => {
    try {
      const { documentId } = req.params;
      const user = req.user as any;
      const userId = user?.claims?.sub || "system";
      const userRole = (req as any).userRole || "patient";
      
      const validationResult = documentAnalysisRequestSchema.safeParse(req.body);
      if (!validationResult.success) {
        return res.status(400).json({ 
          error: "Invalid request data", 
          details: validationResult.error.issues 
        });
      }
      
      const { documentType, title, content, date, provider, patientId, patientContext } = validationResult.data;

      await logPhiAccess({
        userId,
        userRole,
        patientId: patientId || "unknown",
        resourceType: "document_ai_analysis",
        action: "read",
        accessReason: `AI analysis of document: ${title}`,
        ipAddress: req.ip || "unknown",
        userAgent: req.get("user-agent") || "unknown",
        requestPath: req.path,
        requestMethod: req.method,
      });

      const insights = await aiDocInsights.analyzeDocument(
        patientId || "unknown",
        userId,
        userRole,
        {
          documentId,
          documentType,
          title,
          content,
          date: date || new Date().toISOString(),
          provider,
          patientContext,
        }
      );

      // Save the insights
      if (patientId) {
        await storage.createDocumentInsight({
          documentId,
          patientId,
          summary: insights.summary,
          keyFindings: insights.keyFindings,
          trends: insights.trends,
          actionItems: insights.actionItems,
          plainLanguageExplanation: insights.plainLanguageExplanation,
          medicalTermsGlossary: insights.medicalTermsGlossary,
          generatedAt: insights.generatedAt,
          confidenceScore: insights.confidenceScore,
        });
      }

      res.json(insights);
    } catch (error) {
      console.error("[Document Insights] Error analyzing document:", error);
      res.status(500).json({ error: "Failed to analyze document" });
    }
  });

