  // Approve an intervention
  app.post("/api/health-monitoring/interventions/:interventionId/approve", requireRole("provider", "admin"), async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub || "system";
      const userRole = (req as any).userRole || "provider";
      const { interventionId } = req.params;

      await logPhiAccess({
        userId,
        userRole,
        resourceType: "intervention_recommendation",
        resourceId: interventionId,
        action: "write",
        details: `Approve intervention: ${interventionId}`,
      });

      const intervention = await storage.approveIntervention(interventionId, userId);
      if (!intervention) {
        return res.status(404).json({ error: "Intervention not found" });
      }

      res.json(intervention);
    } catch (error) {
      console.error("[Health Monitoring] Error approving intervention:", error);
      res.status(500).json({ error: "Failed to approve intervention" });
    }
  });

  // Complete an intervention
  app.post("/api/health-monitoring/interventions/:interventionId/complete", requireRole("provider", "admin"), async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub || "system";
      const userRole = (req as any).userRole || "provider";
      const { interventionId } = req.params;

      const { completeInterventionRequestSchema } = await import("@shared/schema");
      const parseResult = completeInterventionRequestSchema.safeParse(req.body);
      if (!parseResult.success) {
        return res.status(400).json({ error: "Invalid request", details: parseResult.error.errors });
      }
      const { notes } = parseResult.data;

      await logPhiAccess({
        userId,
        userRole,
        resourceType: "intervention_recommendation",
        resourceId: interventionId,
        action: "write",
        details: `Complete intervention: ${interventionId}`,
      });

      const intervention = await storage.completeIntervention(interventionId, userId, notes);
      if (!intervention) {
        return res.status(404).json({ error: "Intervention not found" });
      }

      res.json(intervention);
    } catch (error) {
      console.error("[Health Monitoring] Error completing intervention:", error);
      res.status(500).json({ error: "Failed to complete intervention" });
    }
  });

  // Analyze patient data and generate alerts/interventions
  app.post("/api/health-monitoring/analyze/:patientId", requireRole("provider", "admin"), async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub || "system";
      const userRole = (req as any).userRole || "provider";
      const { patientId } = req.params;

      await logPhiAccess({
        userId,
        userRole,
        patientId,
        resourceType: "patient_health_analysis",
        action: "read",
        details: `AI proactive health analysis for patient: ${patientId}`,
      });

      const patient = await storage.getPatient(patientId);
      if (!patient) {
        return res.status(404).json({ error: "Patient not found" });
      }

      const vitals = await storage.getVitalsByPatient(patientId);
      const labs = await storage.getLabResultsByPatient(patientId);
      const proms = await storage.getPromResponsesByPatient(patientId);
      const problems = await storage.getProblemsByPatient(patientId);
      const medications = await storage.getMedicationsByPatient(patientId);
      const allergies = await storage.getAllergiesByPatient(patientId);

      const patientData: aiProactiveMonitoring.PatientDataBundle = {
        patientId,
        patientName: `${patient.firstName} ${patient.lastName}`,
        conditions: problems.map(p => p.name),
        medications: medications.map(m => m.name),
        allergies: allergies.map(a => a.allergen),
        vitals,
        labResults: labs,
        promResponses: proms,
      };

      const analysis = await aiProactiveMonitoring.analyzePatientData(patientData, userId, userRole);

      const savedAlerts = [];
      for (const alertData of analysis.alerts) {
        const savedAlert = await storage.createHealthMonitoringAlert(alertData as any);
        savedAlerts.push(savedAlert);
      }

      const savedInterventions = [];
      for (const interventionData of analysis.interventions) {
        const primaryAlertId = savedAlerts.length > 0 ? savedAlerts[0].id : "";
        const intervention = {
          ...interventionData,
          alertId: primaryAlertId,
        };
        const savedIntervention = await storage.createInterventionRecommendation(intervention as any);
        savedInterventions.push(savedIntervention);
      }

      res.json({
        summary: analysis.summary,
        alerts: savedAlerts,
        interventions: savedInterventions,
      });
    } catch (error) {
      console.error("[Health Monitoring] Error analyzing patient:", error);
      res.status(500).json({ error: "Failed to analyze patient data" });
    }
  });

  // Get monitoring dashboard summary
  app.get("/api/health-monitoring/dashboard", requireRole("provider", "admin"), async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub || "system";
      const userRole = (req as any).userRole || "provider";

      await logPhiAccess({
        userId,
        userRole,
        resourceType: "monitoring_dashboard",
        action: "read",
        details: "View health monitoring dashboard",
      });

      const allAlerts = await storage.getHealthMonitoringAlerts();
      const allInterventions = await storage.getInterventionRecommendations();

      const activeAlerts = allAlerts.filter(a => a.status !== "resolved" && a.status !== "dismissed");
      const criticalAlerts = activeAlerts.filter(a => a.severity === "critical").length;
      const highPriorityAlerts = activeAlerts.filter(a => a.severity === "high").length;

      const pendingInterventions = allInterventions.filter(i => i.status === "recommended" || i.status === "approved");
      const resolvedToday = allAlerts.filter(a => {
        if (!a.resolvedAt) return false;
        const resolved = new Date(a.resolvedAt);
        const today = new Date();
        return resolved.toDateString() === today.toDateString();
      }).length;

      const alertsByCategory = [
        { category: "vital_signs", count: activeAlerts.filter(a => a.category === "vital_signs").length },
        { category: "lab_results", count: activeAlerts.filter(a => a.category === "lab_results").length },
        { category: "prom_scores", count: activeAlerts.filter(a => a.category === "prom_scores").length },
        { category: "medication_adherence", count: activeAlerts.filter(a => a.category === "medication_adherence").length },
        { category: "composite_risk", count: activeAlerts.filter(a => a.category === "composite_risk").length },
      ].filter(c => c.count > 0);

      const alertsBySeverity = [
        { severity: "critical", count: criticalAlerts },
        { severity: "high", count: highPriorityAlerts },
        { severity: "medium", count: activeAlerts.filter(a => a.severity === "medium").length },
        { severity: "low", count: activeAlerts.filter(a => a.severity === "low").length },
      ].filter(s => s.count > 0);

      res.json({
        summary: {
          totalMonitoredPatients: new Set(allAlerts.map(a => a.patientId)).size,
          criticalAlerts,
          highPriorityAlerts,
          pendingInterventions: pendingInterventions.length,
          resolvedToday,
          avgResponseTime: 2.5,
        },
        alertsByCategory,
        alertsBySeverity,
        recentAlerts: activeAlerts.slice(0, 10),
        pendingInterventions: pendingInterventions.slice(0, 5),
      });
    } catch (error) {
      console.error("[Health Monitoring] Error fetching dashboard:", error);
      res.status(500).json({ error: "Failed to fetch monitoring dashboard" });
    }
  });

