  // Outbound EHR Data Transmission - Send prescriptions and referrals to external EHRs
  const ehrPrescriptionPayloadSchema = z.object({
    medicationName: z.string().min(1, "Medication name is required"),
    dosage: z.string().min(1, "Dosage is required"),
    frequency: z.string().min(1, "Frequency is required"),
    quantity: z.number().int().positive(),
    refills: z.number().int().min(0).max(12),
    instructions: z.string().optional(),
    patientId: z.string().min(1),
  });

  const ehrReferralPayloadSchema = z.object({
    patientId: z.string().min(1),
    patientName: z.string().min(1),
    specialty: z.string().min(1),
    reasonForReferral: z.string().min(1),
    priority: z.enum(["routine", "urgent", "emergent"]),
    clinicalSummary: z.string().optional(),
    diagnoses: z.array(z.object({
      code: z.string(),
      description: z.string(),
    })).optional(),
  });

  app.post("/api/provider-integration/ehr/connections/:connectionId/send-prescription", requireRole("provider", "admin"), async (req, res) => {
    try {
      const user = req.user as any;
      const { connectionId } = req.params;

      const connection = providerIntegration.ehrIntegrationService.getConnection(connectionId);
      if (!connection) {
        return res.status(404).json({ error: "EHR connection not found" });
      }
      if (connection.status !== "connected") {
        return res.status(400).json({ error: "EHR connection is not active" });
      }

      const validationResult = ehrPrescriptionPayloadSchema.safeParse(req.body);
      if (!validationResult.success) {
        return res.status(400).json({ error: "Invalid prescription data", details: validationResult.error.flatten() });
      }

      const result = await providerIntegration.ehrIntegrationService.sendPrescriptionToEhr(connectionId, validationResult.data);

      logPhiAccess({
        userId: user?.claims?.sub || "system",
        patientId: connection.patientId,
        resourceType: "FHIR_Prescription_Transmission",
        action: "create",
        details: `Sent prescription to ${connection.ehrSystem}: ${result.ehrPrescriptionId}`,
      });

      res.json(result);
    } catch (error: any) {
      console.error("[Provider Integration] Error sending prescription to EHR:", error);
      res.status(500).json({ error: error.message || "Failed to send prescription to EHR" });
    }
  });

