  app.get("/api/provider-integration/providers/telehealth-today", async (req, res) => {
    try {
      const today = new Date();
      const todayStr = today.toISOString().split("T")[0];

      const allProviders = providerIntegration.providerDirectoryService.searchProviders({
        appointmentMode: "telehealth",
      });

      const providersWithTelehealthToday = allProviders.providers.filter((provider: any) => {
        const slots = providerIntegration.availabilityService.getProviderSlots(
          provider.id,
          todayStr,
          todayStr
        );
        return slots.some((slot: any) => 
          slot.status === "available" && 
          slot.appointmentModes.includes("telehealth")
        );
      });

      res.json({
        providers: providersWithTelehealthToday,
        totalCount: providersWithTelehealthToday.length,
        date: todayStr,
      });
    } catch (error) {
      console.error("[Provider Integration] Error fetching telehealth availability:", error);
      res.status(500).json({ error: "Failed to fetch telehealth availability" });
    }
  });

