  app.get("/api/provider-integration/referrals/:referralId", requireRole("patient", "provider", "admin"), async (req, res) => {
    try {
      const user = req.user as any;
      const { referralId } = req.params;
      const userId = user?.claims?.sub;
      const userRole = user?.claims?.role || user?.role;

      const referral = providerIntegration.referralManagementService.getReferral(referralId);
      if (!referral) {
        return res.status(404).json({ error: "Referral not found" });
      }

      if (userRole === "patient" && referral.patientId !== userId) {
        return res.status(403).json({ error: "Access denied" });
      }
      if (userRole === "provider" && referral.referringProviderId !== userId && referral.specialistProviderId !== userId) {
        return res.status(403).json({ error: "Access denied" });
      }

      if (userRole === "provider" && referral.referringProviderId !== userId && referral.specialistProviderId !== userId) {
        return res.status(403).json({ error: "Access denied" });
      }

      logPhiAccess({
        userId: userId || "system",
        patientId: referral.patientId,
        resourceType: "SpecialistReferral",
        action: "read",
        details: `Viewed referral ${referralId}`,
      });

      res.json(referral);
    } catch (error) {
      console.error("[Provider Integration] Error fetching referral:", error);
      res.status(500).json({ error: "Failed to fetch referral" });
    }
  });

