      const { bookingId } = req.params;
      const { reason } = req.body;
      const userId = user?.claims?.sub;
      const userRole = user?.claims?.role || user?.role;

      const existingBooking = providerIntegration.appointmentBookingService.getBooking(bookingId);
      if (!existingBooking) {
        return res.status(404).json({ error: "Booking not found" });
      }

      if (userRole === "patient" && existingBooking.patientId !== userId) {
        return res.status(404).json({ error: "Booking not found" });
      }

      const booking = providerIntegration.appointmentBookingService.cancelBooking(
        bookingId,
        reason || "Cancelled by user",
        userId || "system"
      );

      if (!booking) {
        return res.status(404).json({ error: "Booking not found" });
      }

      logPhiAccess({
        userId: userId || "system",
        patientId: booking.patientId,
        resourceType: "ProviderAppointmentBooking",
        action: "delete",
        details: `Cancelled booking ${bookingId}: ${reason}`,
      });

      res.json(booking);
