  // Generate adherence coaching session
  app.post("/api/ai-medication/coaching", isAuthenticated, async (req, res) => {
    try {
      const user = req.user as any;
      const patientId = user?.claims?.sub || user?.id;
      if (!patientId) return res.status(401).json({ error: "Authentication required" });
      const patientName = user?.claims?.first_name || "Sarah";
      const { medicationId, sessionType } = req.body;

      logPhiAccess({
        userId: patientId,
        patientId,
        resourceType: "AdherenceCoaching",
        action: "ai_generation",
        details: `AI coaching session (${sessionType}) for medication ${medicationId}`,
      });

      const { aiMedicationService } = await import("./ai-medication-service");
      
      // Use unified patient lookup to get medications from all linked EHR sources
      const medications = await storage.getMedicationsByUnifiedPatient(patientId);
      const medication = medications.find(m => m.id === medicationId);
      
      if (!medication) {
        return res.status(404).json({ error: "Medication not found" });
      }
      
      const adherenceRecords = await storage.getMedicationAdherenceRecords(patientId);
      const recentMisses = adherenceRecords
        .filter(r => r.medicationId === medicationId && (r.action === "missed" || r.action === "skipped"))
        .slice(-10);
      
      const session = await aiMedicationService.generateAdherenceCoaching(
        patientId,
        patientName,
        medication,
        recentMisses,
        sessionType || "check_in"
      );

      res.json({
        ...session,
        id: `coaching-${Date.now()}`,
        createdAt: new Date().toISOString(),
        isCompleted: false,
      });
    } catch (error) {
      console.error("[AI Medication] Error generating coaching:", error);
      res.status(500).json({ error: "Failed to generate coaching session" });
    }
  });

  // Get AI medication management dashboard data
  app.get("/api/ai-medication/dashboard", isAuthenticated, async (req, res) => {
    try {
      const user = req.user as any;
      const patientId = user?.claims?.sub || user?.id;
      if (!patientId) return res.status(401).json({ error: "Authentication required" });

      logPhiAccess({
        userId: patientId,
        patientId,
        resourceType: "MedicationDashboard",
        action: "read",
        details: "AI medication dashboard accessed",
      });

      // Use unified patient lookup to get medications from all linked EHR sources
      const medications = await storage.getMedicationsByUnifiedPatient(patientId);
      const adherenceRecords = await storage.getMedicationAdherenceRecords(patientId);
      const reminders = await storage.getMedicationReminders(patientId);
      const interactions = await storage.getDrugInteractions(patientId);

      const totalDoses = adherenceRecords.length || 1;
      const takenDoses = adherenceRecords.filter(r => r.action === "taken").length;
      const overallAdherence = Math.round((takenDoses / totalDoses) * 100);

      const activeInteractions = interactions.filter(i => !i.acknowledgedAt);
      const criticalInteractions = interactions.filter(i => 
        i.severity === "contraindicated" || i.severity === "major"
      );

      res.json({
        summary: {
          totalMedications: medications.length,
          activeMedications: medications.filter(m => m.status === "active").length,
          overallAdherence,
          activeReminders: reminders.filter(r => r.isActive).length,
          pendingInteractions: activeInteractions.length,
          criticalAlerts: criticalInteractions.length,
        },
        medications: medications.slice(0, 10),
        recentAdherence: adherenceRecords.slice(-20).reverse(),
        interactions: interactions.slice(0, 5),
        reminders: reminders.slice(0, 5),
      });
    } catch (error) {
      console.error("[AI Medication] Error getting dashboard:", error);
      res.status(500).json({ error: "Failed to get medication dashboard" });
    }
  });

