  // ==================== Explain Anything Routes ====================
  console.log("[Routes] Explain Anything routes registered at /api/explain");

  const explainFeedbackMap = new Map<string, { helpful: boolean; comment?: string }>();

  app.post("/api/explain/generate", async (req, res) => {
    try {
      const user = req.user as any;
      const patientId = user?.claims?.sub || await getSamplePatientId();
      
      const { explainRequestSchema } = await import("@shared/schema");
      const parseResult = explainRequestSchema.safeParse(req.body);
      if (!parseResult.success) {
        return res.status(400).json({ error: "Invalid request", details: parseResult.error.errors });
      }

      const { checkForMedicalAdviceRequest, isGuardrailTriggered } = await import("./explain-anything-service");
      const fullPrompt = [
        parseResult.data.term,
        parseResult.data.context,
        parseResult.data.sourceQuote?.text,
      ].filter(Boolean).join(" ");
      const guardrailResult = checkForMedicalAdviceRequest(fullPrompt);
      
      if (isGuardrailTriggered(guardrailResult)) {
        await storage.createSecurityAuditLog({
          userId: patientId,
          eventType: "ai_guardrail_triggered",
          description: `Guardrail triggered for medical advice request: ${guardrailResult.triggerReason}`,
          metadata: {
            refusalId: guardrailResult.id,
            triggerReason: guardrailResult.triggerReason,
            detectedPattern: guardrailResult.detectedPattern,
            originalPrompt: "[REDACTED]",
          },
        });
        
        return res.json({ 
          guardrailTriggered: true, 
          refusal: guardrailResult 
        });
      }

      logPhiAccess({
        userId: patientId,
        patientId,
        resourceType: "ExplainAnything",
        action: "read",
        details: `Explanation requested for: ${parseResult.data.term}`,
      });

      await storage.createSecurityAuditLog({
        userId: patientId,
        eventType: "explain_generated",
        description: `Generated explanation for term: ${parseResult.data.term}`,
        metadata: {
          term: parseResult.data.term,
          recordType: parseResult.data.recordType || "general",
          hasSourceQuote: parseResult.data.sourceQuote ? "true" : "false",
        },
      });

      const { generateExplanation } = await import("./explain-anything-service");
      const explanation = await generateExplanation(parseResult.data, patientId);

      res.json(explanation);
    } catch (error) {
      console.error("[ExplainAnything] Error generating explanation:", error);
      res.status(500).json({ error: "Failed to generate explanation" });
    }
  });

