  console.log("[Routes] Timeline Analytics routes registered at /api/timeline/analytics");

  const timelineAnalyticsSchema = z.object({
    eventType: z.enum(["timeline_opened", "timeline_filter_applied", "timeline_item_opened"]),
    metadata: z.record(z.string()).optional(),
  });

  app.post("/api/timeline/analytics", async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub || await getSamplePatientId();
      const ipAddress = req.ip || req.headers["x-forwarded-for"]?.toString() || "Unknown";
      const userAgent = req.headers["user-agent"] || "Unknown";

      const parseResult = timelineAnalyticsSchema.safeParse(req.body);
      if (!parseResult.success) {
        return res.status(400).json({ error: "Invalid request body" });
      }

      const { eventType, metadata } = parseResult.data;

      const descriptions: Record<string, string> = {
        timeline_opened: "User opened the unified timeline",
        timeline_filter_applied: `User applied filter: ${metadata?.filter || "unknown"}`,
        timeline_item_opened: `User opened timeline item: ${metadata?.itemType || "unknown"}`,
      };

      await storage.createSecurityAuditLog({
        eventType,
        userId,
        description: descriptions[eventType] || eventType,
        metadata,
        ipAddress,
        userAgent,
      });

      res.json({ success: true });
    } catch (error) {
      console.error("[Timeline Analytics] Error logging event:", error);
      res.status(500).json({ error: "Failed to log analytics event" });
    }
  });

