  app.get("/api/deduplicated-records/:groupId/provenance", async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub || await getSamplePatientId();
      const { groupId } = req.params;
      const ipAddress = req.ip || req.headers["x-forwarded-for"]?.toString() || "Unknown";
      const userAgent = req.headers["user-agent"] || "Unknown";

      const group = await storage.getDedupGroup(groupId);
      if (!group) {
        return res.status(404).json({ error: "Dedup group not found" });
      }

      const provenanceLinks = await storage.getProvenanceLinksByGroup(groupId);
      const conflicts = await storage.getDedupConflictsByGroup(groupId);

      const { logDedupUserViewedProvenance } = await import("./dedup-service");
      await logDedupUserViewedProvenance(userId, groupId, group.recordType, provenanceLinks.length, ipAddress, userAgent);

      res.json({
        group,
        provenanceLinks,
        conflicts,
      });
    } catch (error) {
      console.error("[Dedup] Error getting provenance:", error);
      res.status(500).json({ error: "Failed to get provenance" });
    }
  });

