    try {
      const user = req.user as any;
      const userId = user?.claims?.sub || await getSamplePatientId();
      const status = req.query.status as "pending" | "resolved" | "dismissed" | undefined;

      const conflicts = await storage.getDedupConflicts(userId, status);

      res.json(conflicts);
    } catch (error) {
      console.error("[Dedup] Error getting conflicts:", error);
      res.status(500).json({ error: "Failed to get dedup conflicts" });
    }
