  const resolveConflictSchema = z.object({
    resolvedValue: z.string().min(1, "Resolution value is required"),
    note: z.string().optional(),
  });

  app.post("/api/dedup-conflicts/:conflictId/resolve", async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub || await getSamplePatientId();
      const { conflictId } = req.params;
      const ipAddress = req.ip || req.headers["x-forwarded-for"]?.toString() || "Unknown";
      const userAgent = req.headers["user-agent"] || "Unknown";

      const parseResult = resolveConflictSchema.safeParse(req.body);
      if (!parseResult.success) {
        return res.status(400).json({ error: "Invalid request body", details: parseResult.error.format() });
      }
      const { resolvedValue, note } = parseResult.data;

      const conflict = await storage.getDedupConflict(conflictId);
      if (!conflict) {
        return res.status(404).json({ error: "Conflict not found" });
      }

      const resolved = await storage.resolveDedupConflict(conflictId, resolvedValue, userId, note);

      const { logDedupConflictResolved } = await import("./dedup-service");
      await logDedupConflictResolved(userId, conflictId, conflict.dedupGroupId, conflict.conflictType, "[REDACTED]", ipAddress, userAgent);

      await storage.updateDedupGroup(conflict.dedupGroupId, {
        conflictCount: (await storage.getDedupConflictsByGroup(conflict.dedupGroupId)).filter(c => c.status === "pending").length,
      });

      res.json(resolved);
    } catch (error) {
      console.error("[Dedup] Error resolving conflict:", error);
      res.status(500).json({ error: "Failed to resolve conflict" });
    }
  });

