  app.delete("/api/privacy/sources/:sourceId", async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub || await getSamplePatientId();
      const ipAddress = (req.headers["x-forwarded-for"] as string) || req.socket?.remoteAddress || "unknown";
      const userAgent = req.headers["user-agent"] || "unknown";

      const parsed = sourceIdSchema.safeParse(req.params);
      if (!parsed.success) {
        return res.status(400).json({ error: "Invalid source ID", details: parsed.error.errors });
      }

      const { getSourceById, revokeSourceAccess } = await import("./privacy-center-service");
      const source = await getSourceById(userId, parsed.data.sourceId);

      logPhiAccess({
        userId,
        patientId: userId,
        resourceType: "ConnectedSource",
        action: "delete",
        details: `Revoked access for source: ${parsed.data.sourceId}`,
      });

      const success = await revokeSourceAccess(userId, parsed.data.sourceId);

      if (!success) {
        return res.status(404).json({ error: "Source not found" });
      }

      await storage.createSecurityAuditLog({
        userId,
        eventType: "data_access",
        description: `Privacy Center: connection_revoked on connection/${parsed.data.sourceId}`,
        ipAddress,
        userAgent,
        metadata: { 
          privacyCenterEvent: "connection_revoked", 
          resourceId: parsed.data.sourceId,
          resourceType: "connection",
          sourceName: source?.name || "unknown",
          sourceType: source?.type || "unknown",
        },
      });
      console.log(`[PrivacyCenter] Analytics event: connection_revoked for user ${userId}`);

      res.json({ success: true });
    } catch (error) {
      console.error("[Privacy] Revoke source error:", error);
      res.status(500).json({ error: "Failed to revoke source" });
    }
  });

