  app.post("/api/privacy/exports", async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub || await getSamplePatientId();
      const ipAddress = (req.headers["x-forwarded-for"] as string) || req.socket?.remoteAddress || "unknown";
      const userAgent = req.headers["user-agent"] || "unknown";

      const parsed = exportRequestSchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({ error: "Invalid export request", details: parsed.error.errors });
      }

      logPhiAccess({
        userId,
        patientId: userId,
        resourceType: "DataExport",
        action: "write",
        details: `Requested ${parsed.data.format} export`,
      });

      await storage.createSecurityAuditLog({
        userId,
        eventType: "data_export",
        description: "Privacy Center: data_export_requested",
        ipAddress,
        userAgent,
        metadata: { 
          privacyCenterEvent: "data_export_requested", 
          format: parsed.data.format,
          categories: parsed.data.categories.join(","),
        },
      });
      console.log(`[PrivacyCenter] Analytics event: data_export_requested for user ${userId}`);

      const { requestDataExport } = await import("./privacy-center-service");
      const exportReq = await requestDataExport(userId, parsed.data.format, parsed.data.categories);

      setTimeout(async () => {
        try {
          await storage.createSecurityAuditLog({
            userId,
            eventType: "data_export",
            description: `Privacy Center: data_export_completed for export/${exportReq.id}`,
            ipAddress,
            userAgent,
            metadata: { 
              privacyCenterEvent: "data_export_completed",
              exportId: exportReq.id,
              format: parsed.data.format,
            },
          });
          console.log(`[PrivacyCenter] Analytics event: data_export_completed for user ${userId}`);
        } catch (e) {
          console.error("[PrivacyCenter] Error logging export completion:", e);
        }
      }, 6000);

      res.status(201).json({ success: true, export: exportReq });
    } catch (error) {
      console.error("[Privacy] Export request error:", error);
      res.status(500).json({ error: "Failed to request export" });
    }
  });

