  const exportIdSchema = z.object({
    exportId: z.string().min(1, "Export ID is required"),
  });

  app.get("/api/privacy/exports/:exportId/download", async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub || await getSamplePatientId();

      const parsed = exportIdSchema.safeParse(req.params);
      if (!parsed.success) {
        return res.status(400).json({ error: "Invalid export ID", details: parsed.error.errors });
      }

      logPhiAccess({
        userId,
        patientId: userId,
        resourceType: "DataExport",
        action: "export",
        details: `Downloaded export: ${parsed.data.exportId}`,
      });

      const { getExportRequests, getDataSummary, getConnectedSources } = await import("./privacy-center-service");
      const exports = await getExportRequests(userId);
      const exp = exports.find((e) => e.id === parsed.data.exportId);

      if (!exp || exp.status !== "completed") {
        return res.status(404).json({ error: "Export not found or not ready" });
      }

      const dataSummary = await getDataSummary(userId);
      const sources = await getConnectedSources(userId);

      if (exp.format === "json") {
        const jsonData = {
          exportId: exp.id,
          format: exp.format,
          exportedAt: exp.completedAt,
          patient: { id: userId },
          dataSummary: dataSummary.categories,
          connectedSources: sources.map((s) => ({
            name: s.name,
            type: s.type,
            status: s.status,
            recordsImported: s.recordsImported,
            connectedAt: s.connectedAt,
            lastSyncAt: s.lastSyncAt,
          })),
          metadata: {
            format: "json",
            version: "1.0.0",
            generatedBy: "Tabula Medica Privacy Center",
          },
        };
        res.setHeader("Content-Type", "application/json");
        res.setHeader("Content-Disposition", `attachment; filename="health-data-export-${parsed.data.exportId}.json"`);
        res.json(jsonData);
      } else if (exp.format === "pdf") {
        const PDFDocument = (await import("pdfkit")).default;
        const doc = new PDFDocument({ margin: 50 });

        res.setHeader("Content-Type", "application/pdf");
        res.setHeader("Content-Disposition", `attachment; filename="health-data-export-${parsed.data.exportId}.pdf"`);

        doc.pipe(res);

        doc.fontSize(24).text("Tabula Medica", { align: "center" });
        doc.fontSize(16).text("Personal Health Data Export", { align: "center" });
        doc.moveDown();
        doc.fontSize(10).text(`Export ID: ${exp.id}`, { align: "center" });
        doc.text(`Generated: ${new Date().toLocaleString()}`, { align: "center" });
        doc.moveDown(2);

        doc.fontSize(14).text("Data Summary", { underline: true });
        doc.moveDown(0.5);
        dataSummary.categories.forEach((cat) => {
          doc.fontSize(11).text(`${cat.name}: ${cat.itemCount} records`);
          doc.fontSize(9).fillColor("gray").text(cat.description);
          doc.fillColor("black").moveDown(0.5);
        });

        doc.moveDown();
        doc.fontSize(14).text("Connected Sources", { underline: true });
        doc.moveDown(0.5);
        sources.forEach((source) => {
          doc.fontSize(11).text(`${source.name} (${source.type})`);
          doc.fontSize(9).fillColor("gray")
            .text(`Status: ${source.status} | Records: ${source.recordsImported}`);
          if (source.lastSyncAt) {
            doc.text(`Last sync: ${new Date(source.lastSyncAt).toLocaleString()}`);
          }
          doc.fillColor("black").moveDown(0.5);
        });

        doc.moveDown(2);
        doc.fontSize(8).fillColor("gray")
          .text("This document was generated by Tabula Medica Privacy Center.", { align: "center" })
          .text("For questions, contact support@tabulamedica.com", { align: "center" });

        doc.end();
      } else {
        const fhirBundle = {
          resourceType: "Bundle",
          id: exp.id,
          type: "collection",
          timestamp: new Date().toISOString(),
          meta: { lastUpdated: new Date().toISOString() },
          entry: dataSummary.categories.map((cat, i) => ({
            resource: {
              resourceType: "DocumentReference",
              id: `doc-${i}`,
              status: "current",
              type: { text: cat.name },
              description: cat.description,
              content: [{ attachment: { title: cat.name } }],
            },
          })),
        };
        res.setHeader("Content-Type", "application/fhir+json");
        res.setHeader("Content-Disposition", `attachment; filename="health-data-export-${parsed.data.exportId}.fhir.json"`);
        res.json(fhirBundle);
      }
    } catch (error) {
      console.error("[Privacy] Export download error:", error);
      res.status(500).json({ error: "Failed to download export" });
    }
  });

