  const aiPreferencesSchema = z.object({
    aiExplanationsEnabled: z.boolean().optional(),
    aiSummariesEnabled: z.boolean().optional(),
  });

  app.put("/api/ai-preferences", async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub || await getSamplePatientId();
      const ipAddress = (req.headers["x-forwarded-for"] as string) || req.socket?.remoteAddress || "unknown";
      const userAgent = req.headers["user-agent"] || "unknown";

      const parsed = aiPreferencesSchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({ error: "Invalid preferences", details: parsed.error.errors });
      }

      const existingPrefs = await storage.getAIPreferences(userId);
      const { aiExplanationsEnabled, aiSummariesEnabled } = parsed.data;

      const updatedPreferences = await storage.createOrUpdateAIPreferences(userId, parsed.data);

      const wasExplanationsEnabled = existingPrefs?.aiExplanationsEnabled ?? true;
      const wasSummariesEnabled = existingPrefs?.aiSummariesEnabled ?? true;
      const nowExplanationsEnabled = aiExplanationsEnabled ?? wasExplanationsEnabled;
      const nowSummariesEnabled = aiSummariesEnabled ?? wasSummariesEnabled;

      if (aiExplanationsEnabled !== undefined && aiExplanationsEnabled !== wasExplanationsEnabled) {
        const eventType = aiExplanationsEnabled ? "ai_explanations_enabled" : "ai_explanations_disabled";
        await storage.createSecurityAuditLog({
          userId,
          eventType: "ai_preferences",
          description: `AI Opt-out: ${eventType}`,
          ipAddress,
          userAgent,
          metadata: { 
            aiOptoutEvent: eventType,
            feature: "explanations",
            enabled: aiExplanationsEnabled,
          },
        });
        console.log(`[AIPreferences] Analytics event: ${eventType} for user ${userId}`);
      }

      if (aiSummariesEnabled !== undefined && aiSummariesEnabled !== wasSummariesEnabled) {
        const eventType = aiSummariesEnabled ? "ai_summaries_enabled" : "ai_summaries_disabled";
        await storage.createSecurityAuditLog({
          userId,
          eventType: "ai_preferences",
          description: `AI Opt-out: ${eventType}`,
          ipAddress,
          userAgent,
          metadata: { 
            aiOptoutEvent: eventType,
            feature: "summaries",
            enabled: aiSummariesEnabled,
          },
        });
        console.log(`[AIPreferences] Analytics event: ${eventType} for user ${userId}`);
      }

      res.json(updatedPreferences);
    } catch (error) {
      console.error("[AIPreferences] Update error:", error);
      res.status(500).json({ error: "Failed to update AI preferences" });
    }
  });

