  // Create new profile (add dependent)
  app.post("/api/profiles", async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub || "current-user";
      const { firstName, lastName, dateOfBirth, gender, relationship, profileType, notes, medicalRecordNumber, insuranceId, emergencyContact } = req.body;

      if (!firstName || !lastName || !relationship) {
        res.status(400).json({ error: "First name, last name, and relationship are required" });
        return;
      }

      const validRelationships = ["self", "child", "parent", "spouse", "sibling", "grandparent", "guardian", "other"];
      if (!validRelationships.includes(relationship)) {
        res.status(400).json({ error: "Invalid relationship type" });
        return;
      }

      // Check if user already has a "self" profile when trying to create another
      if (relationship === "self") {
        const existingProfiles = await storage.getProfiles(userId);
        const hasSelf = existingProfiles.some(p => p.relationship === "self");
        if (hasSelf) {
          res.status(400).json({ error: "You already have a personal (self) profile" });
          return;
        }
      }

      const profile = await storage.createProfile({
        userId,
        firstName,
        lastName,
        dateOfBirth: dateOfBirth || null,
        gender: gender || null,
        profileType: profileType || (relationship === "self" ? "self" : "child"),
        relationship,
        notes: notes || null,
        medicalRecordNumber: medicalRecordNumber || null,
        insuranceId: insuranceId || null,
        emergencyContact: emergencyContact || null,
        status: "active",
      });

      // Track analytics event
      const eventType = relationship === "self" ? "profile_created" : "dependent_added";
      await storage.createProfileAnalyticsEvent({
        userId,
        profileId: profile.id,
        eventType,
        metadata: { relationship, firstName, lastName },
      });

      logPhiAccess({
        userId,
        patientId: profile.id,
        resourceType: "Profile",
        action: "create",
        details: `Created ${relationship} profile: ${firstName} ${lastName}`,
      });

      res.status(201).json(profile);
    } catch (error) {
      console.error("[ProfileManagement] Create profile error:", error);
      res.status(500).json({ error: "Failed to create profile" });
    }
  });

  // Update profile
  app.patch("/api/profiles/:id", async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub || "current-user";
      const { id } = req.params;
      const updates = req.body;

      const existingProfile = await storage.getProfile(id);
      if (!existingProfile || existingProfile.userId !== userId) {
        res.status(404).json({ error: "Profile not found" });
        return;
      }

      // Don't allow changing relationship of self profile
      if (existingProfile.relationship === "self" && updates.relationship && updates.relationship !== "self") {
        res.status(400).json({ error: "Cannot change relationship type of personal profile" });
        return;
      }

      const updatedProfile = await storage.updateProfile(id, updates);

      logPhiAccess({
        userId,
        patientId: id,
        resourceType: "Profile",
        action: "update",
        details: `Updated profile: ${existingProfile.firstName} ${existingProfile.lastName}`,
      });

      res.json(updatedProfile);
    } catch (error) {
      console.error("[ProfileManagement] Update profile error:", error);
      res.status(500).json({ error: "Failed to update profile" });
    }
  });

