  app.delete("/api/profiles/:id", async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub || "current-user";
      const { id } = req.params;

      const profile = await storage.getProfile(id);
      if (!profile || profile.userId !== userId) {
        res.status(404).json({ error: "Profile not found" });
        return;
      }

      // Cannot delete default/self profile
      if (profile.isDefault || profile.relationship === "self") {
        res.status(400).json({ error: "Cannot delete your personal profile" });
        return;
      }

      // Check if this is the last profile
      const allProfiles = await storage.getProfiles(userId);
      if (allProfiles.length <= 1) {
        res.status(400).json({ error: "Cannot delete your only profile" });
        return;
      }

      await storage.deleteProfile(id);

      logPhiAccess({
        userId,
        patientId: id,
        resourceType: "Profile",
        action: "delete",
        details: `Deleted profile: ${profile.firstName} ${profile.lastName} (${profile.relationship})`,
      });

      res.status(204).send();
    } catch (error) {
      console.error("[ProfileManagement] Delete profile error:", error);
      res.status(500).json({ error: "Failed to delete profile" });
    }
  });

