  // Get active shares for a patient
  app.get("/api/quick-share/active", async (req, res) => {
    try {
      const user = req.user as any;
      const patientId = user?.claims?.sub || "patient-default";

      const activeShares: Array<{
        shareId: string;
        recordType: string;
        expiresAt: string;
        accessCount: number;
        createdAt: string;
        revoked: boolean;
        secureLink: string;
        accessLogs: Array<{ timestamp: string; ipAddress: string; userAgent: string }>;
      }> = [];

      quickShareTokens.forEach((data, shareId) => {
        if (data.patientId === patientId && new Date() < data.expiresAt && !data.revoked) {
          activeShares.push({
            shareId,
            recordType: data.recordType,
            expiresAt: data.expiresAt.toISOString(),
            accessCount: data.accessCount,
            createdAt: data.createdAt.toISOString(),
            revoked: data.revoked,
            secureLink: data.secureLink,
            accessLogs: data.accessLogs.map(log => ({
              timestamp: log.timestamp.toISOString(),
              ipAddress: log.ipAddress.substring(0, 10) + "...",
              userAgent: log.userAgent.substring(0, 50) + (log.userAgent.length > 50 ? "..." : ""),
            })),
          });
        }
      });

      res.json(activeShares);
    } catch (error) {
      console.error("[QuickShare] Get active shares error:", error);
      res.status(500).json({ error: "Failed to get active shares" });
    }
  });

