  // Analytics endpoint for provider view events
  app.post("/api/quick-share/analytics", async (req, res) => {
    try {
      const { event, shareId, loadTimeMs } = req.body;

      if (event === "provider_view_opened") {
        await storage.createSecurityAuditLog({
          userId: "external-provider",
          eventType: "provider_view_opened",
          description: "Provider opened shared health record view",
          metadata: { shareId },
        });
      } else if (event === "provider_view_time_to_load_ms") {
        await storage.createSecurityAuditLog({
          userId: "external-provider",
          eventType: "provider_view_time_to_load_ms",
          description: `Provider view loaded in ${loadTimeMs}ms`,
          metadata: { shareId, loadTimeMs: String(loadTimeMs) },
        });
      }

      res.json({ success: true });
    } catch (error) {
      console.error("[QuickShare] Analytics error:", error);
      res.status(500).json({ error: "Failed to log analytics" });
    }
  });

  // Get access log for a specific share
  app.get("/api/quick-share/:shareId/access-log", async (req, res) => {
    try {
      const user = req.user as any;
      const patientId = user?.claims?.sub || "patient-default";
      const { shareId } = req.params;

      const shareData = quickShareTokens.get(shareId);
      if (!shareData) {
        res.status(404).json({ error: "Share not found" });
        return;
      }

      if (shareData.patientId !== patientId) {
        res.status(403).json({ error: "Not authorized to view this access log" });
        return;
      }

      const accessLog = shareData.accessLogs.map(log => ({
        timestamp: log.timestamp.toISOString(),
        ipAddress: log.ipAddress.substring(0, 10) + "...",
        userAgent: log.userAgent.substring(0, 100) + (log.userAgent.length > 100 ? "..." : ""),
      }));

      res.json({
        shareId,
        recordType: shareData.recordType,
        createdAt: shareData.createdAt.toISOString(),
        expiresAt: shareData.expiresAt.toISOString(),
        accessCount: shareData.accessCount,
        accessLog,
      });
    } catch (error) {
      console.error("[QuickShare] Get access log error:", error);
      res.status(500).json({ error: "Failed to get access log" });
    }
  });

  // Revoke a share
  app.delete("/api/quick-share/:shareId", async (req, res) => {
    try {
      const user = req.user as any;
      const patientId = user?.claims?.sub || "patient-default";
      const { shareId } = req.params;

      const shareData = quickShareTokens.get(shareId);
      if (!shareData) {
        res.status(404).json({ error: "Share not found" });
        return;
      }

      if (shareData.patientId !== patientId) {
        res.status(403).json({ error: "Not authorized to revoke this share" });
        return;
      }

      logPhiAccess({
        userId: patientId,
        patientId,
        resourceType: "QuickShare",
        action: "delete",
        details: `Revoked share ${shareId}`,
      });

      // HIPAA audit: share_link_revoked
      await storage.createSecurityAuditLog({
        userId: patientId,
        eventType: "share_link_revoked",
        description: "Patient revoked share link",
        metadata: {
          shareId,
          recordType: shareData.recordType,
          accessCount: String(shareData.accessCount),
        },
      });

      quickShareTokens.delete(shareId);
      res.json({ success: true, message: "Share revoked successfully" });
    } catch (error) {
      console.error("[QuickShare] Revoke error:", error);
      res.status(500).json({ error: "Failed to revoke share" });
    }
  });

