  // ==================== DATA MAPPING ENGINE ====================

  // Analyze source/target formats and generate mappings
  app.post("/api/data-mapping/analyze", async (req, res) => {
    try {
      const { sourceFormat, targetFormat, sourceSample } = req.body as {
        sourceFormat: string;
        targetFormat: string;
        sourceSample?: string;
      };

      // Generate field mappings based on source/target formats
      const fieldMappings: Array<{
        id: string;
        sourceField: string;
        sourcePath: string;
        sourceType: string;
        targetField: string;
        targetPath: string;
        targetType: string;
        confidence: number;
        status: string;
        transformation?: string;
      }> = [];

      const codeTranslations: Array<{
        name: string;
        sourceSystem: string;
        targetSystem: string;
        codeCount: number;
      }> = [];

      // HL7v2 to FHIR Patient mappings
      if (sourceFormat.includes("hl7v2") && targetFormat.includes("fhir_patient")) {
        fieldMappings.push(
          { id: "m1", sourceField: "PID.5.1", sourcePath: "PID-5-1", sourceType: "ST", targetField: "Patient.name.family", targetPath: "Patient.name[0].family", targetType: "string", confidence: 0.98, status: "auto" },
          { id: "m2", sourceField: "PID.5.2", sourcePath: "PID-5-2", sourceType: "ST", targetField: "Patient.name.given", targetPath: "Patient.name[0].given[0]", targetType: "string", confidence: 0.98, status: "auto" },
          { id: "m3", sourceField: "PID.7.1", sourcePath: "PID-7-1", sourceType: "DTM", targetField: "Patient.birthDate", targetPath: "Patient.birthDate", targetType: "date", confidence: 0.95, status: "auto", transformation: "HL7DateTime_to_FHIRDate" },
          { id: "m4", sourceField: "PID.8", sourcePath: "PID-8", sourceType: "IS", targetField: "Patient.gender", targetPath: "Patient.gender", targetType: "code", confidence: 0.92, status: "auto" },
          { id: "m5", sourceField: "PID.11", sourcePath: "PID-11", sourceType: "XAD", targetField: "Patient.address", targetPath: "Patient.address[0]", targetType: "Address", confidence: 0.85, status: "review" },
          { id: "m6", sourceField: "PID.13", sourcePath: "PID-13", sourceType: "XTN", targetField: "Patient.telecom", targetPath: "Patient.telecom[0]", targetType: "ContactPoint", confidence: 0.88, status: "auto", transformation: "HL7XTN_to_FHIRContactPoint" },
          { id: "m7", sourceField: "PID.3.1", sourcePath: "PID-3-1", sourceType: "CX", targetField: "Patient.identifier", targetPath: "Patient.identifier[0].value", targetType: "string", confidence: 0.96, status: "auto" },
          { id: "m8", sourceField: "PID.16", sourcePath: "PID-16", sourceType: "IS", targetField: "Patient.maritalStatus", targetPath: "Patient.maritalStatus.coding[0].code", targetType: "code", confidence: 0.90, status: "auto" },
        );

        codeTranslations.push(
          { name: "Administrative Gender", sourceSystem: "HL7v2 Table 0001", targetSystem: "http://hl7.org/fhir/administrative-gender", codeCount: 4 },
          { name: "Marital Status", sourceSystem: "HL7v2 Table 0002", targetSystem: "http://hl7.org/fhir/marital-status", codeCount: 8 },
          { name: "Address Type", sourceSystem: "HL7v2 Table 0190", targetSystem: "http://hl7.org/fhir/address-type", codeCount: 6 },
        );
      } else if (sourceFormat === "ccda" && targetFormat.includes("fhir")) {
        fieldMappings.push(
          { id: "m1", sourceField: "recordTarget/patient/name/family", sourcePath: "/ClinicalDocument/recordTarget/patientRole/patient/name/family", sourceType: "ST", targetField: "Patient.name.family", targetPath: "Patient.name[0].family", targetType: "string", confidence: 0.96, status: "auto" },
          { id: "m2", sourceField: "recordTarget/patient/name/given", sourcePath: "/ClinicalDocument/recordTarget/patientRole/patient/name/given", sourceType: "ST", targetField: "Patient.name.given", targetPath: "Patient.name[0].given[0]", targetType: "string", confidence: 0.96, status: "auto" },
          { id: "m3", sourceField: "recordTarget/patient/birthTime", sourcePath: "/ClinicalDocument/recordTarget/patientRole/patient/birthTime/@value", sourceType: "TS", targetField: "Patient.birthDate", targetPath: "Patient.birthDate", targetType: "date", confidence: 0.94, status: "auto", transformation: "CCDA_TS_to_FHIRDate" },
        );
        
        codeTranslations.push(
          { name: "Administrative Gender", sourceSystem: "HL7 AdministrativeGender", targetSystem: "http://hl7.org/fhir/administrative-gender", codeCount: 4 },
        );
      } else {
        // Generic custom JSON mappings
        fieldMappings.push(
          { id: "m1", sourceField: "patient.lastName", sourcePath: "$.patient.lastName", sourceType: "string", targetField: "Patient.name.family", targetPath: "Patient.name[0].family", targetType: "string", confidence: 0.85, status: "review" },
          { id: "m2", sourceField: "patient.firstName", sourcePath: "$.patient.firstName", sourceType: "string", targetField: "Patient.name.given", targetPath: "Patient.name[0].given[0]", targetType: "string", confidence: 0.85, status: "review" },
        );
      }

      const avgConfidence = fieldMappings.length > 0 
        ? fieldMappings.reduce((sum, m) => sum + m.confidence, 0) / fieldMappings.length 
        : 0;

      res.json({
        success: true,
        sourceFormat,
        targetFormat,
        fieldMappings,
        codeTranslations,
        summary: {
          totalMappings: fieldMappings.length,
          autoMapped: fieldMappings.filter(m => m.status === "auto").length,
          needsReview: fieldMappings.filter(m => m.status === "review").length,
          avgConfidence: Math.round(avgConfidence * 100),
          codeTranslationCount: codeTranslations.length,
        },
      });
    } catch (error) {
      console.error("[DataMapping] Analysis error:", error);
      res.status(500).json({ error: "Failed to analyze formats" });
    }
  });

