      res.setHeader("Content-Type", "application/pdf");
      res.setHeader("Content-Disposition", "attachment; filename=patient-history.pdf");
      
      doc.pipe(res);
      
      // Title
      doc.fontSize(20).font("Helvetica-Bold").text("Patient-Reported Health History", { align: "center" });
      doc.fontSize(10).font("Helvetica").text(`Generated: ${new Date().toLocaleDateString()}`, { align: "center" });
      doc.moveDown(2);
      
      // Past Medical History
      if (conditions && conditions.length > 0) {
        doc.fontSize(14).font("Helvetica-Bold").text("Past Medical History");
        doc.fontSize(10).font("Helvetica");
        conditions.forEach((c: any, idx: number) => {
          doc.text(`${idx + 1}. ${c.name} (${c.code}) - ${c.status}`);
        });
        doc.moveDown();
      }
      
      // Surgical History
      if (surgeries && surgeries.length > 0) {
        doc.fontSize(14).font("Helvetica-Bold").text("Surgical History");
        doc.fontSize(10).font("Helvetica");
        surgeries.forEach((s: any, idx: number) => {
          doc.text(`${idx + 1}. ${s.name}${s.year ? ` (${s.year})` : ""}`);
        });
        doc.moveDown();
      }
      
      // Allergies
      if (allergies && allergies.length > 0) {
        doc.fontSize(14).font("Helvetica-Bold").text("Allergies");
        doc.fontSize(10).font("Helvetica");
        allergies.forEach((a: any, idx: number) => {
          doc.text(`${idx + 1}. ${a.name} - ${a.type.toUpperCase()} - Severity: ${a.severity}`);
        });
        doc.moveDown();
      }
      
      // Family History
      if (familyHistory && familyHistory.length > 0) {
        doc.fontSize(14).font("Helvetica-Bold").text("Family Medical History");
        doc.fontSize(10).font("Helvetica");
        familyHistory.forEach((f: any) => {
          if (f.conditions && f.conditions.length > 0) {
            doc.text(`${f.relation}: ${f.conditions.join(", ")}`);
          }
        });
        doc.moveDown();
      }
      
      // Social History
      if (socialHistory) {
        doc.fontSize(14).font("Helvetica-Bold").text("Social History");
        doc.fontSize(10).font("Helvetica");
        if (socialHistory.smokingStatus) {
          let smokingText = `Smoking: ${socialHistory.smokingStatus}`;
          if (socialHistory.packsPerDay) smokingText += ` (${socialHistory.packsPerDay} packs/day)`;
          if (socialHistory.smokingYears) smokingText += ` for ${socialHistory.smokingYears} years`;
          doc.text(smokingText);
        }
        if (socialHistory.vapingStatus) doc.text(`Vaping: ${socialHistory.vapingStatus}`);
        if (socialHistory.chewingStatus) doc.text(`Chewing tobacco: ${socialHistory.chewingStatus}`);
        if (socialHistory.alcoholStatus) {
          let alcoholText = `Alcohol: ${socialHistory.alcoholStatus}`;
          if (socialHistory.drinksPerWeek) alcoholText += ` (${socialHistory.drinksPerWeek} drinks/week)`;
          doc.text(alcoholText);
        }
        if (socialHistory.exerciseFrequency) doc.text(`Exercise: ${socialHistory.exerciseFrequency}`);
        if (socialHistory.housingStatus) doc.text(`Housing: ${socialHistory.housingStatus}`);
        if (socialHistory.foodSecurity) doc.text(`Food security: ${socialHistory.foodSecurity}`);
        if (socialHistory.transportationAccess) doc.text(`Transportation: ${socialHistory.transportationAccess}`);
        doc.moveDown();
      }
      
      // Medications
      if (medications && medications.length > 0) {
        doc.fontSize(14).font("Helvetica-Bold").text("Current Medications");
        doc.fontSize(10).font("Helvetica");
        medications.forEach((m: any, idx: number) => {
          doc.text(`${idx + 1}. ${m.name} ${m.strength} - ${m.frequency}`);
        });
        doc.moveDown();
      }
      
      // Footer
      doc.moveDown(2);
      doc.fontSize(8).fillColor("gray");
      doc.text("This document shows patient-reported health history.", { align: "center" });
      doc.text("Information refers to what the patient has provided. Not for diagnostic purposes.", { align: "center" });
      
