  // ============================================
  // DELTA INBOX ("What Changed Since Last Time")
  // ============================================
  console.log("[Routes] Delta Inbox routes registered at /api/delta-inbox");

  const { deltaAnalyticsSchema, markDeltaItemReviewedSchema, DeltaItem } = await import("@shared/schema");

  // In-memory storage for delta items and user sessions (would be DB in production)
  const deltaItems: Map<string, any[]> = new Map();
  const userLoginSessions: Map<string, { lastLoginAt: string; previousLoginAt?: string }> = new Map();

  // Generate sample delta items for a user based on their data
  const generateDeltaItems = async (userId: string): Promise<any[]> => {
    const items: any[] = [];
    const patients = await storage.getPatients();
    const connections = await storage.getEhrConnections();
    
    // Get user's last login to determine what's "new"
    const session = userLoginSessions.get(userId);
    const sinceDate = session?.previousLoginAt 
      ? new Date(session.previousLoginAt)
      : new Date(Date.now() - 7 * 24 * 60 * 60 * 1000); // Default: last 7 days
    
    for (const patient of patients) {
      const connection = connections.find(c => c.id === patient.ehrConnectionId);
      const platform = connection?.platform || "Unknown";
      
      // Check for new lab results
      const records = await storage.getMedicalRecordsByPatient(patient.id);
      for (const record of records) {
        const recordDate = new Date(record.date);
        if (recordDate > sinceDate) {
          items.push({
            id: `delta-${record.id}`,
            userId,
            itemType: record.type === "lab" ? "lab_result" : record.type === "imaging" ? "imaging_result" : "document",
            itemId: record.id,
            title: record.title,
            description: record.description || `New ${record.type} result available`,
            source: platform,
            sourcePlatform: platform,
            createdAt: record.date,
            detectedAt: new Date().toISOString(),
            status: "new",
            priority: record.type === "lab" ? "high" : "medium",
          });
        }
      }
      
      // Check for new medications
      const medications = await storage.getMedicationsByPatient(patient.id);
      for (const med of medications) {
        const medDate = new Date(med.startDate || Date.now());
        if (medDate > sinceDate) {
          items.push({
            id: `delta-med-${med.id}`,
            userId,
            itemType: "medication_started",
            itemId: med.id,
            title: `New Medication: ${med.name}`,
            description: `${med.dosage || ""} - ${med.frequency || ""}`.trim() || "New medication prescribed",
            source: platform,
            sourcePlatform: platform,
            createdAt: med.startDate || new Date().toISOString(),
            detectedAt: new Date().toISOString(),
            status: "new",
            priority: "high",
          });
        }
      }
      
      // Check for new conditions
      const conditions = await storage.getConditionsByPatient(patient.id);
      for (const condition of conditions) {
        const condDate = new Date(condition.diagnosedDate || Date.now());
        if (condDate > sinceDate) {
          items.push({
            id: `delta-cond-${condition.id}`,
            userId,
            itemType: "condition_added",
            itemId: condition.id,
            title: `New Condition: ${condition.name}`,
            description: condition.description || `${condition.status || "Active"} condition added to your record`,
            source: platform,
            sourcePlatform: platform,
            createdAt: condition.diagnosedDate || new Date().toISOString(),
            detectedAt: new Date().toISOString(),
            status: "new",
            priority: condition.status === "active" ? "high" : "medium",
          });
        }
      }
    }
    
    // Sort by date descending (newest first)
    items.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
    
    return items;
  };

  // Get delta inbox items
