    try {
      const user = req.user as any;
      const userId = user?.claims?.sub || await getSamplePatientId();
      const ipAddress = req.ip || req.headers["x-forwarded-for"]?.toString() || "Unknown";
      const userAgent = req.headers["user-agent"] || "Unknown";
      
      const parseResult = markDeltaItemReviewedSchema.safeParse(req.body);
      if (!parseResult.success) {
        return res.status(400).json({ error: "Invalid request body", details: parseResult.error.flatten() });
      }
      
      const { itemIds } = parseResult.data;
      
      let items = deltaItems.get(userId) || [];
      const reviewedAt = new Date().toISOString();
      
      for (const itemId of itemIds) {
        const item = items.find(i => i.id === itemId);
        if (item) {
          item.status = "reviewed";
          item.reviewedAt = reviewedAt;
        }
      }
      
      deltaItems.set(userId, items);
      
      // Log the action
      await storage.createSecurityAuditLog({
        userId,
        eventType: "delta_marked_reviewed",
        description: `User marked ${itemIds.length} delta item(s) as reviewed`,
        metadata: { itemCount: itemIds.length.toString() },
        ipAddress,
        userAgent,
      });
      
      res.json({ success: true, reviewedCount: itemIds.length });
    } catch (error) {
      console.error("[Delta Inbox] Mark reviewed error:", error);
      res.status(500).json({ error: "Failed to mark as reviewed" });
    }
