  // ============================================
  // Document Upload Feature
  // ============================================
  
  const { ObjectStorageService } = await import("./replit_integrations/object_storage/objectStorage");
  const objectStorageService = new ObjectStorageService();
  
  // File validation helper
  const validateFileUpload = (name: string, size: number, contentType: string): { valid: boolean; error?: string } => {
    const { maxFileSize, allowedMimeTypes, allowedExtensions } = FILE_UPLOAD_LIMITS;
    
    // Check file size
    if (size > maxFileSize) {
      return { valid: false, error: `File size exceeds maximum of ${maxFileSize / (1024 * 1024)}MB` };
    }
    
    // Check MIME type
    if (!allowedMimeTypes.includes(contentType as any)) {
      return { valid: false, error: `File type ${contentType} is not allowed. Allowed types: PDF, JPEG, PNG, GIF, WebP, HEIC` };
    }
    
    // Check extension
    const ext = "." + name.split(".").pop()?.toLowerCase();
    if (!allowedExtensions.includes(ext as any)) {
      return { valid: false, error: `File extension ${ext} is not allowed` };
    }
    
    return { valid: true };
  };
  
  // Simple file scanning (MVP: basic content type validation)
  const scanFile = async (fileName: string, contentType: string): Promise<{ status: "clean" | "suspicious" | "error"; message?: string }> => {
    // For MVP, we do basic validation. In production, integrate with a virus scanning service
    try {
      // Check for suspicious file names
      const suspiciousPatterns = [/\.exe$/i, /\.bat$/i, /\.cmd$/i, /\.scr$/i, /\.pif$/i, /\.js$/i, /\.vbs$/i];
      for (const pattern of suspiciousPatterns) {
        if (pattern.test(fileName)) {
          return { status: "suspicious", message: "File type not allowed for security reasons" };
        }
      }
      
      // Check content type matches expected
      if (!contentType.startsWith("application/pdf") && !contentType.startsWith("image/")) {
        return { status: "suspicious", message: "Unexpected content type" };
      }
      
      return { status: "clean" };
    } catch (error) {
      return { status: "error", message: "File scan failed" };
    }
  };

  // Request presigned URL for document upload
  app.post("/api/document-uploads/request-url", requirePermission("documents:read"), async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub || await getSamplePatientId();
      const { name, size, contentType, title, documentDate, documentType, tags } = req.body;
      const ipAddress = req.ip || req.headers["x-forwarded-for"]?.toString() || "Unknown";
      const userAgent = req.headers["user-agent"] || "Unknown";

      // Validate required fields
      if (!name || !size || !contentType) {
        return res.status(400).json({ error: "Missing required fields: name, size, contentType" });
      }
      
      if (!title) {
        return res.status(400).json({ error: "Document title is required" });
      }

      // Validate file
      const validation = validateFileUpload(name, size, contentType);
      if (!validation.valid) {
        // Log failed upload attempt
        await storage.createSecurityAuditLog({
          userId,
          eventType: "document_upload_failed",
          description: `Document upload failed: ${validation.error}`,
          metadata: { fileName: "[REDACTED]", reason: validation.error || "validation_failed" },
          ipAddress,
          userAgent,
        });
        return res.status(400).json({ error: validation.error });
      }

      // Scan file name for security
      const scanResult = await scanFile(name, contentType);
      if (scanResult.status === "suspicious") {
        await storage.createSecurityAuditLog({
          userId,
          eventType: "document_upload_failed",
          description: `Document upload blocked: ${scanResult.message}`,
          metadata: { fileName: "[REDACTED]", reason: "security_scan_failed" },
          ipAddress,
          userAgent,
        });
        return res.status(400).json({ error: scanResult.message });
      }

      // Log upload started
      await storage.createSecurityAuditLog({
        userId,
        eventType: "document_upload_started",
        description: "User started document upload",
        metadata: { 
          documentType: documentType || "other",
          fileSize: size.toString(),
          mimeType: contentType,
        },
        ipAddress,
        userAgent,
      });

      // Get presigned upload URL
      const uploadURL = await objectStorageService.getObjectEntityUploadURL();
      const objectPath = objectStorageService.normalizeObjectEntityPath(uploadURL);

      res.json({
        uploadURL,
        objectPath,
        metadata: { 
          name, 
          size, 
          contentType,
          title,
          documentDate,
          documentType,
          tags,
        },
      });
    } catch (error) {
      console.error("[Document Upload] Request URL error:", error);
      res.status(500).json({ error: "Failed to generate upload URL" });
    }
  });

  // Complete document upload (save metadata after file is uploaded)
