  // Document download endpoint
  app.get("/api/documents/:documentId/download", requirePermission("documents:download"), async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub || await getSamplePatientId();
      const { documentId } = req.params;
      const ipAddress = req.ip || req.headers["x-forwarded-for"]?.toString() || "Unknown";
      const userAgent = req.headers["user-agent"] || "Unknown";

      // Get patient IDs for the user
      const patients = await storage.getPatientsByUserId(userId);
      const patientIds = patients.map(p => p.id);
      
      // Get all documents from connected EHRs
      const connections = await storage.getEhrConnectionsByUserId(userId);
      let document = null;
      
      for (const conn of connections) {
        const docs = await storage.getMedicalRecordsByConnectionId(conn.id);
        const found = docs.find(d => d.id === documentId && patientIds.includes(d.patientId));
        if (found) {
          document = found;
          break;
        }
      }
      
      if (!document) {
        return res.status(404).json({ error: "Document not found" });
      }

      // Log the download event
      await storage.createSecurityAuditLog({
        userId,
        eventType: "document_downloaded",
        description: "User downloaded medical document",
        metadata: {
          documentId: "[REDACTED]",
          documentType: document.resourceType || "unknown",
          action: "download",
        },
        ipAddress,
        userAgent,
      });

      // If document has a file URL, redirect to it
      if (document.fileUrl) {
        return res.redirect(document.fileUrl);
      }

      // Otherwise, generate a downloadable file from content
      const content = document.fhirData ? JSON.stringify(document.fhirData, null, 2) : 
                      document.rawData ? JSON.stringify(document.rawData, null, 2) :
                      "No content available";
      
      const filename = `document-${documentId}.json`;
      
      res.setHeader("Content-Disposition", `attachment; filename="${filename}"`);
      res.setHeader("Content-Type", "application/json");
      res.send(content);
    } catch (error) {
      console.error("[Document Download] Error:", error);
      res.status(500).json({ error: "Failed to download document" });
    }
  });

