  // Record message interaction (for patients)
  app.post("/api/patient-messaging/messages/:id/interaction", requireRole("admin", "provider", "patient"), async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub || user?.id;
      const userRole = user?.role || "patient";
      const { id } = req.params;
      
      const { patientEducationMessagingService } = await import("./services/patientEducationMessagingService");
      
      // Verify message exists and check ownership for patients
      const message = patientEducationMessagingService.getMessageById(id);
      if (!message) {
        return res.status(404).json({ error: "Message not found" });
      }
      
      // Patients can only record interactions on their own messages
      if (userRole === "patient" && message.patientId !== userId) {
        await storage.createSecurityAuditLog({
          userId: userId || "system",
          eventType: "access_denied",
          description: "Unauthorized attempt to record interaction on another patient's message",
          ipAddress: req.ip || "Unknown",
          userAgent: req.headers["user-agent"] || "Unknown",
          metadata: { messageId: id, requestedPatientId: message.patientId },
        });
        return res.status(403).json({ error: "Access denied" });
      }
      
      const { recordInteractionSchema } = await import("@shared/schema");
      const parseResult = recordInteractionSchema.safeParse({ ...req.body, messageId: id });
      
      if (!parseResult.success) {
        return res.status(400).json({ error: "Invalid request body", details: parseResult.error.errors });
      }
      
      const interaction = await patientEducationMessagingService.recordInteraction(
        parseResult.data,
        userId,
        req.ip,
        req.headers["user-agent"]
      );
      
      await storage.createSecurityAuditLog({
        userId: userId || "system",
        eventType: "message_interaction",
        description: `Message ${parseResult.data.interactionType}`,
        ipAddress: req.ip || "Unknown",
        userAgent: req.headers["user-agent"] || "Unknown",
        metadata: { messageId: id, interactionType: parseResult.data.interactionType },
      });
      
      res.json(interaction);
    } catch (error) {
      console.error("[PatientMessaging] Error recording interaction:", error);
      res.status(500).json({ error: "Failed to record interaction" });
    }
  });

