  // Get simplified/important documents list
  app.get("/api/documents/simplified", async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub || "current-user";
      
      const documents = await storage.getDocuments(userId);
      
      const simplifiedDocs = documents.map(doc => ({
        id: doc.id,
        name: doc.name || doc.title || "Untitled Document",
        type: doc.documentType || doc.type || "Document",
        date: new Date(doc.createdAt || Date.now()).toLocaleDateString(),
        isImportant: doc.tags?.includes("important") || doc.category === "critical" || false,
      }));
      
      res.json(simplifiedDocs);
    } catch (error) {
      console.error("[SimplifiedMode] Documents error:", error);
      res.json([]);
    }
  });

  // Get last uploaded document
  app.get("/api/documents/last-upload", async (req, res) => {
    try {
      const user = req.user as any;
      const userId = user?.claims?.sub || "current-user";
      
      const documents = await storage.getDocuments(userId);
      
      if (documents.length === 0) {
        return res.json(null);
      }
      
      const sorted = documents.sort((a, b) => 
        new Date(b.createdAt || 0).getTime() - new Date(a.createdAt || 0).getTime()
      );
      
      const lastDoc = sorted[0];
      res.json({
        id: lastDoc.id,
        name: lastDoc.name || lastDoc.title || "Untitled",
        date: new Date(lastDoc.createdAt || Date.now()).toLocaleDateString(),
      });
    } catch (error) {
      console.error("[SimplifiedMode] Last upload error:", error);
      res.json(null);
    }
  });

